export const jobSource="\"\"\"Fixed Colab job launched through the authenticated Jupyter API; no web server.\"\"\"\nimport hashlib, json, os, subprocess, sys, time, re, shutil\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent\nPART = 2 * 1024 * 1024\n_SEPARATION_READY = False\n\n\ndef status(state, message, **extra):\n    tmp = ROOT/'state.tmp'\n    tmp.write_text(json.dumps(dict(state=state, message=message, updated=time.time(), **extra), ensure_ascii=False))\n    tmp.replace(ROOT/'state.json')\n\n\ndef assemble(config):\n    source = ROOT/('source.'+config['ext'])\n    if config.get('parentJob'):\n        parent_id=config['parentJob']\n        if not re.fullmatch(r'[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}',parent_id):raise ValueError('مرجع مصدر غير صالح')\n        parent=ROOT.parent/parent_id;old=json.loads((parent/'config.json').read_text())\n        if config.get('task')!=old.get('task') or config.get('task') not in {'asr','ocr','cutout','word','translate','burn','convert','resize'} or any(old.get(k)!=config.get(k) for k in ['ext','size','chunks','sha256']):raise ValueError('مرجع المصدر لا يطابق العملية السابقة')\n        src=parent/('source.'+config['ext'])\n        if not src.is_file():raise ValueError('المصدر المحفوظ غير مكتمل؛ أعد رفع الملف بدل إعادة المحاولة من المصدر')\n        digest=hashlib.sha256();size=0\n        with src.open('rb') as inp,source.open('wb') as out:\n            while True:\n                data=inp.read(PART)\n                if not data:break\n                size+=len(data);digest.update(hashlib.sha256(data).digest());out.write(data)\n        if size!=config['size'] or digest.hexdigest()!=config['sha256']:\n            source.unlink(missing_ok=True);raise ValueError('لم يطابق المصدر المحفوظ بصمته؛ أعد رفعه')\n        return source\n\n    digest = hashlib.sha256()\n    with source.open('wb') as out:\n        for i in range(config['chunks']):\n            part = ROOT/f'input_{i:05d}.bin'\n            data = part.read_bytes()\n            if len(data) != min(PART, config['size']-i*PART):\n                raise ValueError('حجم جزء الرفع لا يطابق المصدر؛ أعد الرفع')\n            digest.update(hashlib.sha256(data).digest())\n            out.write(data)\n    if source.stat().st_size != config['size'] or digest.hexdigest() != config['sha256']:\n        source.unlink(missing_ok=True)\n        raise ValueError('لم يكتمل نقل الملف بشكل سليم؛ أعد الرفع')\n    for part in ROOT.glob('input_*.bin'):\n        part.unlink()\n    return source\n\n\ndef failure_details(exc,cfg):\n import traceback\n text=str(exc).lower();kind=type(exc).__name__;module=type(exc).__module__\n known=['CONTENT_REVIEW_REQUIRED','CONTENT_REVIEW_ERROR','VIDEOGEN_TEXT_SETUP','MODEL_META_TENSOR','TRANSLATION_WORKER_STOPPED','DEPENDENCY_TIMEOUT','DEPENDENCY_INSTALL','PYTHON_ENV_SETUP','JS_CHECKSUM','PLATFORM_VERIFICATION','LOGIN_REQUIRED','DRM','JS_CHALLENGE','PLATFORM_NETWORK','DOWNLOAD_NETWORK','EXTRACTOR_FAILED','DOWNLOAD_FAILED','ASR_TIMESTAMPS','ASR_NO_SPEECH']\n code=next((c for c in known if '· '+c in str(exc)),None)\n if not code:\n  if isinstance(exc,ImportError):code='MODEL_IMPORT_INCOMPATIBLE'\n  elif 'meta tensor' in text:code='MODEL_META_TENSOR'\n  elif 'out of memory' in text:code='GPU_MEMORY'\n  elif isinstance(exc,subprocess.TimeoutExpired):code='PROCESS_TIMEOUT'\n  elif isinstance(exc,subprocess.CalledProcessError):code='MEDIA_PROCESS_FAILED'\n  elif isinstance(exc,ModuleNotFoundError):code='MODULE_MISSING'\n  elif any(x in text for x in ['cudnn','cublas','cuda','undefined symbol']):code='GPU_LIBRARY'\n  elif kind in {'GatedRepoError','RepositoryNotFoundError','EntryNotFoundError'}:code='MODEL_NOT_ACCESSIBLE'\n  elif any(x in (module+' '+kind).lower() for x in ['huggingface','httpx','requests','urllib3']) or any(x in text for x in ['timed out','connection reset','connection aborted']):code='MODEL_DOWNLOAD_FAILED'\n  elif any(x in text for x in ['safetensor','weights_only','state_dict','tokenizer','from_pretrained']):code='MODEL_LOAD_FAILED'\n  else:code='TOOL_'+re.sub('[^A-Z0-9_]','',kind.upper())[:60]\n friendly={'MODEL_IMPORT_INCOMPATIBLE':'تعذر توافق استيراد مكتبات النموذج؛ التشخيص يتضمن الرمز أو المكتبة الناقصة','MODEL_META_TENSOR':'أوزان النموذج غير محمّلة فعليًا؛ رُفض نقل أوزان فارغة إلى GPU','GPU_MEMORY':'نفدت ذاكرة GPU؛ قلّل مدة اللقطة أو اختر ذاكرة أكبر','MODULE_MISSING':'لم تكتمل إحدى مكتبات الأداة؛ أعد المحاولة في الجلسة نفسها','GPU_LIBRARY':'تعذر توافق مكتبة GPU؛ جرّب مسار التوافق أو جلسة جديدة','DEPENDENCY_TIMEOUT':'انتهت مهلة تجهيز المكتبات؛ أعد المحاولة في الجلسة نفسها','PROCESS_TIMEOUT':'انتهت مهلة مرحلة المعالجة؛ المصدر محفوظ للمحاولة التالية','DEPENDENCY_INSTALL':'تعذر تثبيت مكتبات الأداة المتوافقة','MEDIA_PROCESS_FAILED':'تعذر فك أو ترميز الملف؛ تحقق من وجود صوت أو فيديو صالح','MODEL_NOT_ACCESSIBLE':'ملف النموذج المطلوب غير متاح من مزوده','MODEL_DOWNLOAD_FAILED':'تعذر تنزيل ملفات النموذج؛ الملفات المكتملة محفوظة ويمكن استكمالها','MODEL_LOAD_FAILED':'تعذر تحميل النموذج أو توافق أوزانه؛ تفاصيل التشخيص مرفقة'}\n frames=[{'file':Path(f.filename).name,'line':f.lineno,'function':f.name} for f in traceback.extract_tb(exc.__traceback__) if Path(f.filename).name in {'madar_cloud_tasks.py','runner.py','madar_web_job.py','madar_colab_runtime.py','madar_download.py','pipeline_wan.py','transformer_wan.py','autoencoder_kl_wan.py','modeling_utils.py','modeling_m2m_100.py','import_utils.py'}][-8:]\n versions={}\n task=cfg.get('task','separate') if isinstance(cfg,dict) else 'unknown'\n packages=['yt-dlp','yt-dlp-ejs'] if task=='download' else ['torch','ctranslate2','faster-whisper','transformers','diffusers','onnxruntime-gpu','huggingface-hub','tokenizers','safetensors','accelerate','ftfy']\n for name in packages:\n  try:\n   import importlib.metadata\n   versions[name]=importlib.metadata.version(name)\n  except importlib.metadata.PackageNotFoundError:pass\n task=cfg.get('task','separate') if isinstance(cfg,dict) else 'unknown'\n loaded_versions={n:getattr(sys.modules.get(n),'__version__',None) for n in ['torch','transformers','accelerate','tokenizers','safetensors','huggingface_hub'] if sys.modules.get(n) is not None}\n signature=re.search(r\"cannot import name ['\\\"]([A-Za-z_][A-Za-z0-9_]{0,79})['\\\"] from ['\\\"]([A-Za-z_][A-Za-z0-9_.]{0,159})['\\\"]\",str(exc))\n undefined=getattr(exc,'name',None) if isinstance(exc,NameError) else None\n diagnostic={'task':task,'exception':kind if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,79}',kind) else 'Unknown','frames':frames,'versions':versions,'loadedVersions':loaded_versions}\n if code in {'CONTENT_REVIEW_REQUIRED','CONTENT_REVIEW_ERROR'}:diagnostic.update(stage='content_review',generationCompleted=code=='CONTENT_REVIEW_REQUIRED')\n if code=='CONTENT_REVIEW_REQUIRED':\n  details=getattr(exc,'review_details',{})\n  review={k:details[k] for k in ['firstFlaggedFrame','timestampMs','checkedFrames','totalFrames','fps'] if isinstance(details.get(k),int) and not isinstance(details[k],bool) and 0<=details[k]<=1000000}\n  review.update(precision='float32',decision='flagged_frame')\n  if details.get('checker')=='Falconsai/nsfw_image_detection' and details.get('revision')=='96cb0d0342c7afb80cab76ecc58b265fa44da256':review.update(checker=details['checker'],revision=details['revision'],policy='binary_classifier_default')\n  diagnostic['review']=review\n if isinstance(undefined,str) and re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,79}',undefined):diagnostic['undefinedName']=undefined\n if signature:diagnostic['missingImport']={'symbol':signature[1],'module':signature[2]}\n media=getattr(exc,'media_details',None)\n if isinstance(media,dict) and media.get('code') in {'MEDIA_NO_VIDEO','MEDIA_NO_AUDIO','MEDIA_DECODER_UNAVAILABLE','MEDIA_INVALID_INPUT','MEDIA_DISK_FULL','MEDIA_RESOURCE_BUSY','MEDIA_TIMEOUT','MEDIA_PROCESS_FAILED'}:\n  safe={'code':media['code'],'stage':media.get('stage') if media.get('stage') in {'source_probe','audio_decode','output_encode'} else 'unknown'}\n  if isinstance(media.get('exitCode'),int):safe['exitCode']=media['exitCode']\n  diagnostic['media']=safe\n  return media['code'],str(exc)[:300],diagnostic\n if getattr(exc,'worker_diagnostic',None):return exc.worker_diagnostic['code'],exc.worker_diagnostic['message'].split(' · ')[0],exc.worker_diagnostic['diagnostic']\n # Only our explicit Arabic ValueErrors can be shown, without URLs or source paths.\n msg=str(exc).split(' · ')[0] if isinstance(exc,ValueError) and re.search('[\\u0600-\\u06ff]',str(exc)) and not re.search(r'https?://|[/\\\\]|ya29\\.|gsk_',str(exc)) else friendly.get(code,'فشلت مرحلة في الأداة؛ التشخيص مرفق دون محتوى ملفك')\n return code,msg[:400],diagnostic\n\n\ndef main():\n    global _SEPARATION_READY\n    ROOT.mkdir(exist_ok=True)\n    # Atomic lock prevents an uncertain websocket reply from starting a second job.\n    try:\n        lock = os.open(str(ROOT/'started.lock'), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)\n        os.close(lock)\n    except FileExistsError:\n        return\n    cfg={}\n    try:\n        cfg = json.loads((ROOT/'config.json').read_text())\n        if cfg.get('task') == 'download':\n            from madar_download import download_clip\n            output = download_clip(cfg, ROOT, status)\n        elif cfg.get('task') in {'ocr','cutout','word','asr','translate','burn','convert','resize','imagegen','videogen'}:\n            from madar_cloud_tasks import process\n            source=assemble(cfg) if cfg.get('size') else None\n            output=process(cfg['task'],source,cfg,ROOT,status)\n        else:\n            status('setup', 'تثبيت مكتبات الفصل على Colab؛ أول تشغيل قد يستغرق عدة دقائق')\n            if not _SEPARATION_READY:\n                from madar_colab_runtime import install_once, SEPARATION_PIP\n                install_once('separation', SEPARATION_PIP)\n                _SEPARATION_READY = True\n            status('gpu', 'تحميل النموذج واختبار CUDA فعليًا')\n            import madar_colab_runtime as runtime\n            source = assemble(cfg)\n            runtime.validate_audio_source(source)\n            runtime.prepare_gpu()\n            # Progress is emitted by the existing tested chunk engine, with measured ETA.\n            class ProgressLog:\n                def __init__(self): self.pending = ''\n                def write(self, text):\n                    sys.__stdout__.write(text)\n                    self.pending += text\n                    if '\\n' in self.pending:\n                        lines = self.pending.split('\\n')\n                        self.pending = lines.pop()\n                        for line in lines:\n                            if line.strip(): status('separating', line.strip()[:500])\n                def flush(self): sys.__stdout__.flush()\n            sys.stdout = ProgressLog()\n            if cfg.get('task') == 'dub':\n                def dub_lines(voice, work):\n                    # Text is a helper: if it fails the visitor still gets the stems and can dub.\n                    if cfg.get('textLang', 'none') == 'none':\n                        return []\n                    try:\n                        from madar_cloud_tasks import dub_text\n                        data = dub_text(voice, cfg['textLang'], status)\n                    except Exception as exc:\n                        data = {'error': (str(exc) or type(exc).__name__)[:300], 'lines': []}\n                    target = work/'lines.json'\n                    target.write_text(json.dumps(data, ensure_ascii=False), encoding='utf-8')\n                    return [target]\n                output = runtime.run_dub_stems(source, extra=dub_lines)\n            else:\n                output = runtime.run_separation(source, cfg['start'], cfg['duration'], cfg['mode'], **({'output_format':cfg['outputFormat']} if cfg.get('outputFormat') else {}))\n            sys.stdout = sys.__stdout__\n        if output.stat().st_size<1:raise ValueError('لم تنتج الأداة ملفًا صالحًا')\n        if output.stat().st_size > 256*1024**2:\n            raise ValueError('الناتج يتجاوز حد التنزيل الآمن للمتصفح 256 MB؛ اختر MP3 أو M4A للصوت، أو جزءًا أقصر')\n        chunks = []\n        with output.open('rb') as f:\n            while True:\n                block = f.read(PART)\n                if not block: break\n                index = len(chunks)\n                (ROOT/f'output_{index:05d}.bin').write_bytes(block)\n                chunks.append(hashlib.sha256(block).hexdigest())\n        captions={}\n        if cfg.get('task')=='asr' and output.suffix=='.mp4':\n            import zipfile\n            sidecar=ROOT/'caption-files.zip'\n            with zipfile.ZipFile(sidecar,'w',zipfile.ZIP_DEFLATED) as z:\n                for name in ['original.srt','transcript.txt','translated.srt','rendered.srt']:\n                    if (ROOT/name).is_file():z.write(ROOT/name,name)\n            hashes=[]\n            with sidecar.open('rb') as f:\n                while True:\n                    block=f.read(PART)\n                    if not block:break\n                    (ROOT/f'captions_{len(hashes):05d}.bin').write_bytes(block);hashes.append(hashlib.sha256(block).hexdigest())\n            captions={'size':sidecar.stat().st_size,'chunks':hashes,'ext':'zip'}\n        preview={}\n        if (ROOT/'preview.json').exists():preview=json.loads((ROOT/'preview.json').read_text())\n        status('done', 'اكتملت المعالجة؛ النتيجة جاهزة للتنزيل', size=output.stat().st_size, chunks=chunks, ext=output.suffix.lower().lstrip('.'), task=cfg.get('task','separate'), designName=cfg.get('name',''),sourceName=cfg.get('sourceName',''),preview=preview,captions=captions)\n    except Exception as exc:\n        # Detailed traceback remains in the user's runtime, never in the page response.\n        import traceback\n        traceback.print_exc()\n        code,msg,diagnostic=failure_details(exc,cfg)\n        status('error',msg+' · '+code,code=code,diagnostic=diagnostic)\n\n\nif __name__ == '__main__':\n    main()\n";
export const engineSource="\"\"\"Madar GPU separation, run interactively inside the user's own Colab notebook.\nNo tunnel, web server, remote-control endpoint or account credential is created.\n\"\"\"\nimport gc, hashlib, json, logging, math, shutil, subprocess, sys, time\nfrom functools import lru_cache\nfrom pathlib import Path\n\nMODEL = 'UVR-MDX-NET-Voc_FT.onnx'\n# Dubbing needs a background with no voice left in it. Measured on a speech + music test mix,\n# Voc_FT left the voice clearly audible in its instrumental (+12.4 dB during speech) while the\n# instrumental-trained Inst_HQ_4 left almost none (+2.3 dB), so dubbing uses Inst_HQ_4.\nDUB_MODEL = 'UVR-MDX-NET-Inst_HQ_4.onnx'\nROOT = Path('/content/madar_separation')\nCACHE = Path('/content/madar_models')\nCHUNK_SECONDS = 300\nSEPARATION_PIP = [['install', '--quiet', 'audio-separator[gpu]==0.48.0', 'onnxruntime-gpu[cuda,cudnn]==1.23.2', 'numpy==2.2.6', 'numba==0.61.2', 'nvidia-cublas-cu12>=12,<13']]\nSETUP_DIR = Path(__file__).resolve().parent/'setup'\n\n\ndef install_once(key, commands, timeout=600):\n    \"\"\"Runs the pip commands for `key` once per Colab session. A shared lock lets the early\n    preparation (started while the file uploads) and the job itself use the same install:\n    whichever comes second waits for the first and then skips it. Returns True if it installed.\"\"\"\n    import fcntl\n    SETUP_DIR.mkdir(parents=True, exist_ok=True)\n    tag = hashlib.sha256(json.dumps(commands).encode()).hexdigest()[:16]\n    marker = SETUP_DIR/(key+'.ok')\n    def ready():\n        try: return marker.read_text() == tag\n        except OSError: return False\n    if ready(): return False\n    with open(SETUP_DIR/'pip.lock', 'a') as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX)\n        if ready(): return False\n        for command in commands:\n            subprocess.run([sys.executable, '-m', 'pip', *command], check=True, timeout=timeout)\n        marker.write_text(tag)\n    return True\n\n\ndef chunk_plan(total, start=0, duration=0, chunk_seconds=CHUNK_SECONDS):\n    total, start, duration = float(total), float(start), float(duration)\n    if not all(map(math.isfinite, (total, start, duration))) or total <= 0 or start < 0 or duration < 0 or start >= total or chunk_seconds <= 0:\n        raise ValueError('حدّد بداية ومدة صحيحتين داخل المصدر؛ صفر للمدة يعني كامل المتبقي')\n    length = min(duration or total-start, total-start)\n    return [(start+i*chunk_seconds, min(chunk_seconds, length-i*chunk_seconds)) for i in range(math.ceil(length/chunk_seconds))]\n\n\nclass MediaError(RuntimeError):\n    def __init__(self, code, stage, exit_code=None):\n        messages={'MEDIA_NO_VIDEO':'المصدر صوت فقط؛ اختر صيغة صوتية بدل الفيديو','MEDIA_NO_AUDIO':'المقطع لا يحتوي على مسار صوت يمكن فصله','MEDIA_DECODER_UNAVAILABLE':'ترميز المصدر غير متاح في محرك هذه الجلسة','MEDIA_INVALID_INPUT':'تعذر قراءة المصدر؛ قد يكون الملف تالفًا أو غير مكتمل','MEDIA_DISK_FULL':'امتلأت مساحة جلسة المعالجة','MEDIA_RESOURCE_BUSY':'موارد فك الترميز مشغولة؛ أعد المحاولة بعد انتهاء المعالجة الأخرى','MEDIA_TIMEOUT':'انتهت مهلة معالجة الوسائط','MEDIA_PROCESS_FAILED':'تعذر فك أو ترميز الوسائط؛ راجع رمز المرحلة في تفاصيل الدعم'}\n        super().__init__(messages.get(code,messages['MEDIA_PROCESS_FAILED']))\n        self.media_details={'code':code,'stage':stage}\n        if isinstance(exit_code,int):self.media_details['exitCode']=exit_code\n\n\ndef media_failure(stderr):\n    text=(stderr or '').lower()\n    if any(x in text for x in ['no space left','disk quota exceeded']):return 'MEDIA_DISK_FULL'\n    if any(x in text for x in ['resource temporarily unavailable','pthread_create','cannot allocate memory','out of memory']):return 'MEDIA_RESOURCE_BUSY'\n    if any(x in text for x in ['matches no streams','does not contain any stream','no audio stream']):return 'MEDIA_NO_AUDIO'\n    if any(x in text for x in ['unknown decoder','decoder not found','decoding requested, but no decoder found','unsupported codec']):return 'MEDIA_DECODER_UNAVAILABLE'\n    if any(x in text for x in ['invalid data found','moov atom not found','error opening input']):return 'MEDIA_INVALID_INPUT'\n    return 'MEDIA_PROCESS_FAILED'\n\n\ndef ffmpeg(args):\n    args=list(map(str,args));stage='audio_decode' if 'pcm_s16le' in args and '-ss' in args else 'output_encode'\n    # Bound decoder/filter threads on shared and small-RAM Colab instances.\n    command=['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-y','-protocol_whitelist','file,pipe','-threads','2','-filter_threads','1','-filter_complex_threads','1',*args[:-1],'-threads','2',args[-1]]\n    for attempt in range(2):\n        try:p=subprocess.run(command,capture_output=True,text=True,timeout=1800)\n        except subprocess.TimeoutExpired:raise MediaError('MEDIA_TIMEOUT',stage) from None\n        if not p.returncode:return\n        code=media_failure(p.stderr)\n        if code=='MEDIA_RESOURCE_BUSY' and attempt==0:\n            \n            for at,value in enumerate(command[:-1]):\n                if value=='-threads':command[at+1]='1'\n            print('تخفيف موارد فك الترميز وإعادة محاولة المرحلة الحالية…',flush=True)\n            continue\n        # Never expose raw stderr: it can contain source paths or metadata.\n        raise MediaError(code,stage,p.returncode)\n\n\ndef validate_audio_source(source):\n    try:streams=media_streams(source)\n    except subprocess.TimeoutExpired:raise MediaError('MEDIA_TIMEOUT','source_probe') from None\n    except subprocess.CalledProcessError as exc:raise MediaError(media_failure(exc.stderr),'source_probe',exc.returncode) from None\n    if not any(item.get('codec_type')=='audio' for item in streams):raise MediaError('MEDIA_NO_AUDIO','source_probe')\n\n\nAUDIO_FORMATS={'m4a':['-c:a','aac','-b:a','192k','-movflags','+faststart'],'mp3':['-c:a','libmp3lame','-b:a','192k'],'wav':['-c:a','pcm_s16le'],'flac':['-c:a','flac'],'ogg':['-c:a','libvorbis','-q:a','5'],'opus':['-c:a','libopus','-b:a','160k'],'aac':['-c:a','aac','-b:a','192k']}\nVIDEO_FORMATS={'mp4','mkv','mov','webm','avi','ts'}\n\n\ndef export_media(source,target,quality='balanced',audio_source=None,start=0,duration=0):\n    target=Path(target);fmt=target.suffix[1:].lower()\n    if fmt in AUDIO_FORMATS:\n        ffmpeg(['-i',source,'-map','0:a:0','-vn','-ac','2',*AUDIO_FORMATS[fmt],'-map_metadata','-1',target]);return target\n    if fmt not in VIDEO_FORMATS:raise ValueError('صيغة الناتج غير مدعومة')\n    if not any(s.get('codec_type')=='video' for s in media_streams(source)):raise MediaError('MEDIA_NO_VIDEO','source_probe')\n    q={'high':'20','balanced':'25','small':'30'}[quality]\n    before=['-ss',start,'-i',source]\n    if audio_source:before+=['-i',audio_source]\n    if duration:before+=['-t',duration]\n    before+=['-map','0:v:0','-map','1:a:0' if audio_source else '0:a:0?']\n    if fmt=='webm':codec=['-c:v','libvpx-vp9','-crf',q,'-b:v','0','-deadline','good','-cpu-used','4'];audio=['-c:a','libopus','-b:a','160k']\n    elif fmt=='avi':codec=['-c:v','mpeg4','-q:v','4'];audio=['-c:a','libmp3lame','-b:a','192k']\n    else:\n        copy=bool(audio_source) and not start and not duration and (fmt=='mkv' or compatible_mp4(source)[0])\n        codec=['-c:v','copy'] if copy else video_encoder()\n        if not copy:\n            flag='-cq' if 'h264_nvenc' in codec else '-crf';codec=list(codec);codec[codec.index(flag)+1]=q\n        audio=['-c:a','aac','-b:a','192k']\n    tail=['-map_metadata','-1',*(['-movflags','+faststart'] if fmt in {'mp4','mov'} else []),target]\n    try:ffmpeg([*before,*codec,*audio,*tail])\n    except RuntimeError:\n        if 'h264_nvenc' not in codec:raise\n        print('تعذر NVENC؛ استكمال إخراج الفيديو على CPU دون إعادة الفصل',flush=True)\n        ffmpeg([*before,'-c:v','libx264','-preset','veryfast','-crf',q,'-pix_fmt','yuv420p',*audio,*tail])\n    return target\n\n\nNVENC_DIAGNOSTIC='NOT_CHECKED'\n\n@lru_cache(maxsize=1)\ndef gpu_name():\n    try:\n        p=subprocess.run(['nvidia-smi','--query-gpu=name','--format=csv,noheader'],capture_output=True,text=True,timeout=5)\n        name=getattr(p,'stdout','') or ''\n        return name.splitlines()[0].strip()[:100] if name else ''\n    except (OSError,subprocess.SubprocessError):return ''\n\n\ndef nvenc_failure(message):\n    message=message.lower()\n    if 'unknown encoder' in message:return 'ENCODER_NOT_BUILT'\n    if any(t in message for t in ['libnvidia-encode','cannot load libcuda','cannot load libnvcuvid']):return 'DRIVER_LIBRARY_MISSING'\n    if any(t in message for t in ['api version','minimum required nvidia driver']):return 'DRIVER_API_MISMATCH'\n    if any(t in message for t in ['minimum supported','width is too small','height is too small']):return 'ENCODER_PROBE_DIMENSIONS'\n    if 'no nvenc capable devices' in message:return 'GPU_ENCODER_UNAVAILABLE'\n    if 'out of memory' in message or 'resource temporarily unavailable' in message:return 'ENCODER_RESOURCE_BUSY'\n    return 'GPU_ENCODER_UNAVAILABLE'\n\n\ndef nvenc_explanation():\n    descriptions={'HARDWARE_NO_NVENC':'هذه البطاقة لا تحتوي مرمّز NVENC عتاديًا','ENCODER_NOT_BUILT':'نسخة FFmpeg لا تتضمن مرمّز NVENC','DRIVER_LIBRARY_MISSING':'مكتبة ترميز NVIDIA غير متاحة داخل جلسة Colab','DRIVER_API_MISMATCH':'نسخة FFmpeg تتطلب واجهة تعريف NVIDIA مختلفة','ENCODER_PROBE_DIMENSIONS':'رفض المرمّز مقاس اختبار القدرات','ENCODER_RESOURCE_BUSY':'موارد مرمّز NVIDIA مشغولة مؤقتًا','ENCODER_PROBE_FAILED':'تعذر إكمال اختبار ترميز NVIDIA','GPU_ENCODER_UNAVAILABLE':'لم يسمح المورد الحالي بفتح مرمّز NVIDIA'}\n    return descriptions.get(NVENC_DIAGNOSTIC,'لم ينجح فحص ترميز NVIDIA')+' · '+NVENC_DIAGNOSTIC\n\n\n@lru_cache(maxsize=1)\ndef nvenc_ready():\n    global NVENC_DIAGNOSTIC\n    \"\"\"A real encoding probe, not just presence in ffmpeg -encoders.\"\"\"\n    if any(model in gpu_name().upper() for model in ['A100','H100','H200','B200']):\n        NVENC_DIAGNOSTIC='HARDWARE_NO_NVENC';return False\n    try:\n        result = subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-f','lavfi','-i','color=c=black:s=256x256:r=30:d=0.1','-frames:v','2','-pix_fmt','yuv420p','-c:v','h264_nvenc','-preset','p4','-f','null','-'], capture_output=True, timeout=15)\n        if result.returncode==0:\n            NVENC_DIAGNOSTIC='READY'\n            return True\n        message=getattr(result,'stderr',b'')\n        if isinstance(message,bytes):message=message.decode('utf-8','replace')\n        message=message.lower()\n        NVENC_DIAGNOSTIC=nvenc_failure(message)\n        return False\n    except (OSError, subprocess.SubprocessError):\n        NVENC_DIAGNOSTIC='ENCODER_PROBE_FAILED'\n        return False\n\n\ndef video_encoder():\n    if nvenc_ready():\n        return ['-c:v','h264_nvenc','-preset','p4','-rc','vbr','-cq','20','-b:v','0','-pix_fmt','yuv420p']\n    return ['-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p']\n\n\ndef media_streams(path):\n    result = subprocess.run(['ffprobe','-v','error','-protocol_whitelist','file,pipe','-show_entries','stream=codec_type,codec_name,pix_fmt','-of','json',str(path)],capture_output=True,text=True,check=True,timeout=30)\n    return json.loads(result.stdout).get('streams',[])\n\n\ndef compatible_mp4(path):\n    streams = media_streams(path)\n    video = next((s for s in streams if s.get('codec_type')=='video'),{})\n    audio = next((s for s in streams if s.get('codec_type')=='audio'),None)\n    return video.get('codec_name')=='h264' and video.get('pix_fmt') in {'yuv420p','yuvj420p','nv12'}, audio is None or audio.get('codec_name')=='aac'\n\n\ndef prepare_mp4(source, target, report):\n    copy_video, copy_audio = compatible_mp4(source)\n    codec = ['-c:v','copy'] if copy_video else video_encoder()\n    def encode(chosen):\n        return subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-y','-protocol_whitelist','file,pipe','-i',str(source),'-map','0:v:0','-map','0:a:0?',*chosen,*(['-c:a','copy'] if copy_audio else ['-c:a','aac','-b:a','160k']),'-map_metadata','-1','-movflags','+faststart',str(target)],check=True,timeout=1200)\n    report('downloading','تجهيز MP4 دون إعادة ترميز الفيديو أو تغيير جودته' if copy_video else 'ترميز الفيديو على GPU · NVENC' if 'h264_nvenc' in codec else 'ترميز CPU لهذا الفيديو؛ '+nvenc_explanation())\n    try:\n        encode(codec)\n    except subprocess.CalledProcessError:\n        if 'libx264' in codec: raise\n        fallback = video_encoder() if copy_video else ['-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p']\n        report('downloading','إعادة تجهيز الفيديو بمرمّز متوافق بعد تعذر المسار الأسرع')\n        encode(fallback)\n    return Path(target)\n\n\ndef duration_of(path):\n    p = subprocess.run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration', '-of', 'json', str(path)], capture_output=True, text=True, check=True)\n    value = float(json.loads(p.stdout)['format']['duration'])\n    if not math.isfinite(value) or value <= 0:\n        raise ValueError('تعذر تحديد مدة المصدر')\n    return value\n\n\ndef sha256(path):\n    digest = hashlib.sha256()\n    with Path(path).open('rb') as f:\n        for block in iter(lambda: f.read(1024*1024), b''):\n            digest.update(block)\n    return digest.hexdigest()\n\n\ndef session_from_separator(separator):\n    fn = separator.model_instance.model_run\n    for cell in (getattr(fn, '__closure__', None) or []):\n        value = cell.cell_contents\n        if hasattr(value, 'get_providers') and 'CUDAExecutionProvider' in value.get_providers():\n            return value\n    raise RuntimeError('لم يتفعّل CUDA فعليًا؛ لا توجد عودة إلى CPU في هذا الدفتر')\n\n\ndef new_separator(output_dir, single_stem='Vocals', model=None):\n    from audio_separator.separator import Separator\n    obj = Separator(output_dir=str(output_dir), model_file_dir=str(CACHE), output_format='WAV', output_single_stem=single_stem, use_soundfile=True,\n                    log_level=logging.WARNING, mdx_params={'hop_length':1024, 'segment_size':256, 'overlap':0.25, 'batch_size':1, 'enable_denoise':False})\n    obj.load_model(model_filename=model or MODEL)\n    session_from_separator(obj)\n    return obj\n\n\ndef prepare_gpu():\n    import numpy as np\n    import onnxruntime as ort\n    if hasattr(ort, 'preload_dlls'):\n        ort.preload_dlls(directory='')\n    import torch\n    ROOT.mkdir(parents=True, exist_ok=True)\n    CACHE.mkdir(parents=True, exist_ok=True)\n    if not torch.cuda.is_available():\n        raise RuntimeError('اختر T4 GPU من إعدادات وقت التشغيل في Colab ثم شغّل الخلية مجددًا')\n    probe_dir = ROOT/'probe'\n    probe_dir.mkdir(exist_ok=True)\n    probe = new_separator(probe_dir)\n    session = session_from_separator(probe)\n    result = session.run(None, {'input':np.zeros((1,4,3072,256), dtype=np.float32)})[0]\n    if not np.isfinite(result).all():\n        raise RuntimeError('اختبار GPU لم يُنتج بيانات سليمة')\n    device = torch.cuda.get_device_name(0)\n    del result, session, probe\n    gc.collect()\n    print('جاهز: تم اختبار CUDA فعليًا على', device)\n    return device\n\n\ndef source_fingerprint(path, start, duration, mode):\n    path = Path(path).resolve()\n    stat = path.stat()\n    digest = hashlib.sha256(str((str(path), stat.st_size, stat.st_mtime_ns, float(start), float(duration), mode)).encode())\n    with path.open('rb') as f:\n        digest.update(f.read(65536))\n        if stat.st_size > 65536:\n            f.seek(max(0, stat.st_size-65536))\n            digest.update(f.read(65536))\n    return digest.hexdigest()[:24]\n\n\ndef run_separation(source, start=0, duration=0, mode='audio', output_format=None):\n    source = Path(source).resolve()\n    if not source.is_file() or source.stat().st_size == 0:\n        raise ValueError('المصدر غير موجود أو فارغ')\n    if mode not in {'audio','video'}:\n        raise ValueError('نوع الناتج غير صالح')\n    if output_format is not None and output_format not in (VIDEO_FORMATS if mode=='video' else AUDIO_FORMATS):\n        raise ValueError('صيغة الناتج لا تطابق نوع الملف')\n    plan = chunk_plan(duration_of(source), start, duration)\n    length = sum(seconds for _,seconds in plan)\n    if shutil.disk_usage(ROOT).free < 2*1024**3:\n        raise RuntimeError('مساحة Colab المتبقية أقل من 2 GB')\n    work = ROOT/source_fingerprint(source,start,duration,mode)\n    work.mkdir(exist_ok=True)\n    manifest = work/'checkpoint.json'\n    try:\n        completed = json.loads(manifest.read_text())\n    except (ValueError, OSError):\n        completed = {}\n    print('عدد الأجزاء:',len(plan),'· مدة المصدر المختارة:',round(length,1),'ثانية')\n    print('الأجزاء المكتملة تُحفظ داخل هذه الجلسة لاستكمالها إذا أعدت تشغيل خلية الفصل بنفس المصدر والإعدادات.')\n    separator = new_separator(work)\n    voices = []\n    measured = 0.0\n    measured_count = 0\n    try:\n        for index,(at,seconds) in enumerate(plan):\n            saved = completed.get(str(index),{})\n            name = saved.get('name','')\n            cached = work/name\n            if name and Path(name).name == name and cached.is_file() and sha256(cached) == saved.get('sha256'):\n                voices.append(cached)\n                print(f'{index+1}/{len(plan)} · استكمال الجزء المحفوظ')\n                continue\n            if shutil.disk_usage(ROOT).free < 512*1024**2:\n                raise RuntimeError('المساحة لا تكفي للجزء التالي؛ الأجزاء المكتملة محفوظة في الجلسة')\n            began = time.monotonic()\n            remaining = f' · المتبقي تقريبًا {math.ceil((len(plan)-index)*measured/measured_count)} ثانية' if measured_count else ' · قياس سرعة أول جزء'\n            print(f'{index+1}/{len(plan)} · فصل على GPU'+remaining,flush=True)\n            raw = work/f'chunk_{index:05d}.wav'\n            try:\n                ffmpeg(['-ss',at,'-i',source,'-t',seconds,'-map','0:a:0','-vn','-ac','2','-ar','44100','-c:a','pcm_s16le',raw])\n                names = separator.separate(str(raw), custom_output_names={'Vocals':f'voice_{index:05d}'})\n                if not names:\n                    raise RuntimeError('لم يُنتج نموذج الفصل ملفًا')\n                result = Path(names[0])\n                if not result.is_absolute():\n                    result = work/result\n                if not result.is_file():\n                    raise RuntimeError('ملف الجزء المفصول غير موجود')\n                voices.append(result)\n                completed[str(index)] = {'name':result.name,'sha256':sha256(result)}\n                temp = work/'checkpoint.tmp'\n                temp.write_text(json.dumps(completed))\n                temp.replace(manifest)\n            finally:\n                raw.unlink(missing_ok=True)\n            measured += time.monotonic()-began\n            measured_count += 1\n        listing = work/'voice_list.txt'\n        listing.write_text(''.join(\"file '\"+str(p)+\"'\\n\" for p in voices))\n        audio = work/'voice.m4a'\n        print('جمع الأجزاء وحفظ M4A…',flush=True)\n        ffmpeg(['-f','concat','-safe','0','-i',listing,'-c:a','aac','-b:a','192k','-movflags','+faststart',audio])\n        if output_format is not None:\n            if mode=='video':\n                output=export_media(source,work/('result.'+output_format),audio_source=audio,start=start,duration=length if (start or duration) else 0)\n            elif output_format=='m4a':output=audio\n            else:output=export_media(audio,work/('voice.'+output_format))\n        elif mode == 'video':\n            output = work/'result.mkv'\n            codec = ['-c:v','copy'] if float(start)==0 and float(duration)==0 else video_encoder()\n            print('تجهيز الفيديو: '+('نسخ الصورة الأصلية دون إعادة ترميز' if 'copy' in codec else 'GPU · NVENC' if 'h264_nvenc' in codec else 'CPU؛ NVENC غير متاح في هذه الجلسة'),flush=True)\n            before=['-ss',start,'-i',source,'-i',audio,'-t',length,'-map','0:v:0','-map','1:a:0','-map','0:s?']\n            after=['-c:a','copy','-c:s','copy','-map_metadata','-1',output]\n            try:\n                ffmpeg([*before,*codec,*after])\n            except RuntimeError:\n                if 'h264_nvenc' not in codec: raise\n                print('تعذر ترميز هذا الفيديو عبر NVENC؛ استكمال الإخراج على CPU دون إعادة الفصل',flush=True)\n                ffmpeg([*before,'-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p',*after])\n        else:\n            output = audio\n        print('اكتمل:',output,'·',round(output.stat().st_size/1024**2,1),'MB')\n        return output\n    finally:\n        del separator\n        gc.collect()\n\n\nSENTENCE_END = ('.', '?', '!', '؟', '…', '。', '!', '؛')\n\n\ndef _ends_sentence(word):\n    return str(word.get('w', '')).rstrip().rstrip('\"\\'»)').endswith(SENTENCE_END)\n\n\ndef _speaker(chunk):\n    voices = [w.get('spk') for w in chunk if w.get('spk') is not None]\n    return max(set(voices), key=voices.count) if voices else None\n\n\ndef merge_fragments(lines, words=2, seconds=0.6, gap=0.8, back_gap=2.0):\n    \"\"\"A piece of one or two words (or under a second) is almost always part of a sentence that\n    was cut, not a sentence of its own, so it joins its neighbour: the line before it when that\n    line has not ended its sentence, otherwise the line after it when this piece has not ended\n    its own sentence and the next line is the same (or an unknown) speaker. A full reply such as\n    «نعم يا أمي.» keeps its own line.\"\"\"\n    lines = [list(l) for l in lines]\n    i = 0\n    while i < len(lines):\n        cur = lines[i]\n        short = len(cur) <= words or cur[-1]['e'] - cur[0]['s'] < seconds\n        if short:\n            prev = lines[i-1] if i > 0 else None\n            nxt = lines[i+1] if i + 1 < len(lines) else None\n            same = lambda other: _speaker(cur) is None or _speaker(other) is None or _speaker(cur) == _speaker(other)\n            # A short piece that ends its own sentence with another voice is a reply («نعم.»).\n            if prev and not _ends_sentence(prev[-1]) and cur[0]['s'] - prev[-1]['e'] < back_gap and (same(prev) or not _ends_sentence(cur[-1])):\n                prev.extend(cur); del lines[i]; i = max(i - 1, 0); continue\n            if nxt and not _ends_sentence(cur[-1]) and nxt[0]['s'] - cur[-1]['e'] < gap and same(nxt):\n                cur.extend(nxt); del lines[i+1]; continue\n        i += 1\n    return lines\n\n\ndef group_dub_words(words, sounds=(), pause_turn=0.0, long_gap=2.0, max_len=20.0, pause_mark=0.7, attach=0.6, pad_start=0.05, pad_end=0.12):\n    \"\"\"Turns Whisper word timings into dubbing lines that a performer can say in one breath.\n    A line is a whole sentence of one speaker: it ends at a sentence end, when the speaker\n    changes ('spk' on the words, from voice embeddings), or at a very long silence. Short\n    pauses inside a sentence never cut it, so «وأنا | أمك» stays one line. Only a line longer\n    than max_len is split, preferring sentence ends, then Whisper segments, then the widest pause.\n    sounds: [{'s','e','label'}] — laughs, hums, sighs… found where the voice track has sound but\n    Whisper wrote no word. Each joins the nearest line as «(ضحكة)», or becomes its own line.\n    Long silences inside a line show as «…» so the performer knows to wait.\"\"\"\n    words = sorted((w for w in words if str(w.get('w', '')).strip() and w.get('e', 0) > w.get('s', 0)), key=lambda w: w['s'])\n    known = any(w.get('spk') is not None for w in words)\n    lines, cur = [], []\n    def close():\n        if cur: lines.append(list(cur)); cur.clear()\n    for w in words:\n        if cur:\n            prev = cur[-1]; pause = w['s'] - prev['e']\n            # Voice labels are noisy (one person can look like two), so a new speaker only\n            # starts a line where there is also a real break: a pause or a new Whisper segment.\n            turn = (known and w.get('spk') is not None and prev.get('spk') is not None and w['spk'] != prev['spk']\n                    and (pause >= pause_turn or w.get('seg') != prev.get('seg')))\n            # Without speaker labels a new Whisper segment after a real breath is the best\n            # remaining hint of a new sentence or speaker.\n            segment = w.get('seg') != prev.get('seg') and pause >= (0.3 if known else 0.15)\n            if turn or pause >= long_gap or (_ends_sentence(prev) and pause >= 0.08) or segment:\n                close()\n        cur.append(w)\n    close()\n    lines = merge_fragments(lines)\n    out = []\n    def split(chunk):\n        if chunk[-1]['e'] - chunk[0]['s'] <= max_len or len(chunk) < 2:\n            out.append(chunk); return\n        middle = (chunk[0]['s'] + chunk[-1]['e']) / 2\n        def score(j):\n            prev, nxt = chunk[j-1], chunk[j]\n            return (_ends_sentence(prev), prev.get('seg') != nxt.get('seg'), round(nxt['s'] - prev['e'], 1), -abs(nxt['s'] - middle))\n        k = max(range(1, len(chunk)), key=score)\n        split(chunk[:k]); split(chunk[k:])\n    if not known:\n        max_len = min(max_len, 8.0)\n    for chunk in lines: split(chunk)\n    # Non-speech sounds join the closest line (inside it or within `attach` seconds of it).\n    extra = []\n    for snd in sorted(sounds or [], key=lambda x: x['s']):\n        if not (snd.get('e', 0) > snd.get('s', 0) and str(snd.get('label', '')).strip()):\n            continue\n        item = {'w': '(' + str(snd['label']).strip() + ')', 's': snd['s'], 'e': snd['e'], 'k': 'sound'}\n        best, gap = None, attach\n        for chunk in out:\n            d = max(0.0, chunk[0]['s'] - snd['e'], snd['s'] - chunk[-1]['e'])\n            if d <= gap:\n                best, gap = chunk, d\n        if best is None:\n            extra.append([item])\n        else:\n            best.append(item); best.sort(key=lambda x: x['s'])\n    out = sorted(out + extra, key=lambda c: c[0]['s'])\n    result = []\n    for chunk in out:\n        items = []\n        for w in chunk:\n            if items and w.get('k') is None and items[-1].get('k') is None and w['s'] - items[-1]['e'] >= pause_mark:\n                items.append({'w': '…', 's': round(items[-1]['e'], 2), 'e': round(w['s'], 2), 'k': 'pause'})\n            items.append(w)\n        start = max(0.0, chunk[0]['s'] - pad_start); end = chunk[-1]['e'] + pad_end\n        if result and start < result[-1]['end']:\n            mid = round((result[-1]['words'][-1]['e'] + chunk[0]['s']) / 2, 2); result[-1]['end'] = max(mid, result[-1]['words'][-1]['e']); start = result[-1]['end']\n        line = {'start': round(start, 2), 'end': round(max(end, start + 0.2), 2), 'text': ' '.join(str(w['w']).strip() for w in items),\n                'say': ' '.join(str(w['w']).strip() for w in items if w.get('k') is None),\n                'words': [{'w': str(w['w']).strip(), 's': round(w['s'], 2), 'e': round(w['e'], 2), **({'k': w['k']} if w.get('k') else {})} for w in items]}\n        voices = [w['spk'] for w in chunk if w.get('spk') is not None]\n        if voices:\n            line['spk'] = max(set(voices), key=voices.count)\n        result.append(line)\n    return result\n\n\ndef speech_units(words, gap=0.2):\n    \"\"\"Groups words into short stretches of continuous speech: the pieces whose voices are\n    compared to tell speakers apart. Returns lists of word indexes.\"\"\"\n    units, cur = [], []\n    for i, w in enumerate(words):\n        if cur:\n            prev = words[cur[-1]]\n            if w['s'] - prev['e'] >= gap or w.get('seg') != prev.get('seg') or _ends_sentence(prev):\n                units.append(cur); cur = []\n        cur.append(i)\n    if cur: units.append(cur)\n    return units\n\n\ndef cluster_speakers(vectors, threshold=0.8):\n    \"\"\"Average-linkage clustering of voice embeddings by cosine similarity. Entries that are\n    None (pieces too short to judge) get None. Labels are numbered by first appearance.\"\"\"\n    import numpy as np\n    idx = [i for i, v in enumerate(vectors) if v is not None]\n    labels = [None] * len(vectors)\n    if not idx:\n        return labels\n    x = np.array([np.asarray(vectors[i], dtype=np.float64) for i in idx])\n    x /= np.maximum(np.linalg.norm(x, axis=1, keepdims=True), 1e-9)\n    if len(idx) == 1:\n        raw = [0]\n    else:\n        try:\n            from scipy.cluster.hierarchy import linkage, fcluster\n            raw = list(fcluster(linkage(x, method='average', metric='cosine'), t=1 - threshold, criterion='distance'))\n        except ImportError:\n            raw = _average_linkage(x, threshold)\n    order = {}\n    for i, g in zip(idx, raw):\n        labels[i] = order.setdefault(g, len(order) + 1)\n    return labels\n\n\ndef _average_linkage(x, threshold):\n    import numpy as np\n    total = x @ x.T; np.fill_diagonal(total, 0.0)\n    groups = {i: [i] for i in range(len(x))}\n    while len(groups) > 1:\n        keys = list(groups)\n        sizes = np.array([len(groups[k]) for k in keys], dtype=np.float64)\n        sub = total[np.ix_(keys, keys)] / np.outer(sizes, sizes)\n        np.fill_diagonal(sub, -np.inf)\n        a, b = np.unravel_index(int(np.argmax(sub)), sub.shape)\n        if sub[a, b] < threshold:\n            break\n        ga, gb = keys[a], keys[b]\n        total[ga, :] += total[gb, :]; total[:, ga] += total[:, gb]; total[ga, ga] = 0.0\n        groups[ga] += groups.pop(gb)\n    raw = [0] * len(x)\n    for g, members in groups.items():\n        for m in members: raw[m] = g\n    return raw\n\n\ndef speech_windows(words, units, win=1.2, hop=0.4, min_len=0.45):\n    \"\"\"Short overlapping windows over each unit, so a speaker change inside continuous speech\n    (Whisper's word times often hide the gap between two people) can still be found.\n    Returns [(unit index, start, end)].\"\"\"\n    out = []\n    for u, unit in enumerate(units):\n        a, b = words[unit[0]]['s'] - 0.05, words[unit[-1]]['e'] + 0.05\n        if b - a < min_len:\n            continue\n        if b - a <= win + hop / 2:\n            out.append((u, a, b)); continue\n        t = a\n        while t + win < b:\n            out.append((u, t, t + win)); t += hop\n        out.append((u, b - win, b))\n    return out\n\n\ndef assign_speakers(words, units, windows, labels, min_run=0.6):\n    \"\"\"Gives every word the speaker of the windows that cover it most, then removes flickers:\n    a speaker run shorter than min_run seconds inside a unit takes its neighbour's label. Words\n    with no judged window (very short pieces) take a neighbour in the same Whisper segment.\"\"\"\n    for u, unit in enumerate(units):\n        mine = [(a, b, l) for (wu, a, b), l in zip(windows, labels) if wu == u and l is not None]\n        for i in unit:\n            w = words[i]; votes = {}\n            for a, b, l in mine:\n                overlap = min(b, w['e']) - max(a, w['s'])\n                if overlap > 0:\n                    votes[l] = votes.get(l, 0) + overlap\n            w['spk'] = max(votes, key=votes.get) if votes else None\n        changed = True\n        while changed:\n            changed = False\n            runs = []\n            for i in unit:\n                if runs and runs[-1][0] == words[i]['spk']:\n                    runs[-1][1].append(i)\n                else:\n                    runs.append([words[i]['spk'], [i]])\n            if len(runs) < 2:\n                break\n            for r, (lab, idx) in enumerate(runs):\n                length = words[idx[-1]]['e'] - words[idx[0]]['s']\n                if lab is not None and length >= min_run:\n                    continue\n                left = runs[r-1] if r > 0 else None; right = runs[r+1] if r + 1 < len(runs) else None\n                pick = max([x for x in (left, right) if x and x[0] is not None], default=None,\n                           key=lambda x: words[x[1][-1]]['e'] - words[x[1][0]]['s'])\n                if pick is not None and pick[0] != lab:\n                    for i in idx: words[i]['spk'] = pick[0]\n                    changed = True; break\n    for u, unit in enumerate(units):\n        if all(words[i]['spk'] is None for i in unit):\n            for j in (u-1, u+1):\n                if 0 <= j < len(units) and words[units[j][0]].get('seg') == words[unit[0]].get('seg') and words[units[j][0]].get('spk') is not None:\n                    lab = words[units[j][0 if j > u else -1]]['spk']\n                    for i in unit: words[i]['spk'] = lab\n                    break\n    return words\n\n\nSOUND_LABELS = [\n    ('ضحكة', ['Laughter', 'Baby laughter', 'Giggle', 'Snicker', 'Belly laugh', 'Chuckle, chortle']),\n    ('همهمة', ['Humming']),\n    ('تنهيدة', ['Sigh']),\n    ('شهقة', ['Gasp']),\n    ('كحة', ['Cough', 'Throat clearing']),\n    ('بكاء', ['Crying, sobbing', 'Baby cry, infant cry', 'Whimper', 'Wail, moan']),\n    ('صرخة', ['Screaming', 'Yell', 'Shout', 'Children shouting', 'Battle cry']),\n    ('تأوه', ['Groan', 'Grunt']),\n    ('تنفس', ['Breathing', 'Pant', 'Wheeze']),\n    ('همس', ['Whispering']),\n    ('عطسة', ['Sneeze']),\n]\nSPEECH_LABELS = ['Speech', 'Child speech, kid speaking', 'Conversation', 'Narration, monologue', 'Babbling', 'Male speech, man speaking', 'Female speech, woman speaking']\n\n\nSOUND_MARK = '…'\n\n\ndef name_sound(scores, seconds, min_sound=0.1, min_speech=0.3):\n    \"\"\"Mark for a non-word sound made by a person (laugh, hum, sigh, «أمم»…), from AudioSet\n    scores {label: probability}. The sound is not named — naming it was often wrong (a squeal\n    shown as crying) — the performer only needs to know something other than words is there.\n    Music, effects and other leftovers on the voice track get None.\"\"\"\n    vocal = max((scores.get(l, 0.0) for _, labels in SOUND_LABELS for l in labels), default=0.0)\n    speech = max((scores.get(l, 0.0) for l in SPEECH_LABELS), default=0.0)\n    return SOUND_MARK if vocal >= min_sound or speech >= min_speech else None\n\n\ndef sound_regions(samples, rate, words, frame=0.03, min_len=0.25, join=0.25, guard=0.08):\n    \"\"\"Stretches where the separated voice track has sound but Whisper wrote no word.\"\"\"\n    import numpy as np\n    samples = np.asarray(samples, dtype=np.float32)\n    size = max(1, int(round(frame * rate))); count = len(samples) // size\n    if not count:\n        return []\n    rms = np.sqrt(np.mean(samples[:count*size].reshape(count, size) ** 2, axis=1))\n    floor, peak = np.quantile(rms, 0.2), np.quantile(rms, 0.95)\n    if peak < 0.003:\n        return []\n    on = rms > max(floor * 3, peak * 0.12, 0.004)\n    for w in words:\n        a = max(0, int((w['s'] - guard) / frame)); b = min(count, int(np.ceil((w['e'] + guard) / frame)))\n        on[a:b] = False\n    regions, start = [], None\n    for f in range(count + 1):\n        active = f < count and on[f]\n        if active and start is None: start = f\n        if not active and start is not None: regions.append([start * frame, f * frame]); start = None\n    merged = []\n    for a, b in regions:\n        if merged and a - merged[-1][1] < join: merged[-1][1] = b\n        else: merged.append([a, b])\n    return [{'s': round(a, 2), 'e': round(b, 2)} for a, b in merged if b - a >= min_len]\n\n\ndef run_dub_stems(source, extra=None):\n    \"\"\"Dubbing preparation: split the whole source into the human voice and everything else\n    (ambient sound, effects, music). Both stems come back sample-aligned in one ZIP so the\n    browser can find speech timings from voice.m4a and mix new recordings over background.m4a.\"\"\"\n    import zipfile\n    source = Path(source).resolve()\n    if not source.is_file() or source.stat().st_size == 0:\n        raise ValueError('المصدر غير موجود أو فارغ')\n    total = duration_of(source)\n    if total > 30*60:\n        raise ValueError('حد الدبلجة 30 دقيقة للمقطع؛ اختر مقطعًا أقصر')\n    plan = chunk_plan(total, chunk_seconds=CHUNK_SECONDS)\n    if shutil.disk_usage(ROOT).free < 2*1024**3:\n        raise RuntimeError('مساحة Colab المتبقية أقل من 2 GB')\n    work = ROOT/('dub2-'+source_fingerprint(source, 0, 0, 'audio'))\n    work.mkdir(parents=True, exist_ok=True)\n    print('تجهيز الدبلجة · عدد الأجزاء:', len(plan), '· المدة:', round(total, 1), 'ثانية', flush=True)\n    separator = new_separator(work, single_stem=None, model=DUB_MODEL)\n    voices, backgrounds = [], []\n    try:\n        for index, (at, seconds) in enumerate(plan):\n            print(f'{index+1}/{len(plan)} · فصل الأصوات البشرية عن المحيط على GPU', flush=True)\n            raw = work/f'chunk_{index:05d}.wav'\n            try:\n                ffmpeg(['-ss', at, '-i', source, '-t', seconds, '-map', '0:a:0', '-vn', '-ac', '2', '-ar', '44100', '-c:a', 'pcm_s16le', raw])\n                names = separator.separate(str(raw), custom_output_names={'Vocals': f'voice_{index:05d}', 'Instrumental': f'bg_{index:05d}'})\n                found = {}\n                for name in names or []:\n                    path = Path(name)\n                    path = path if path.is_absolute() else work/path\n                    if path.name.startswith('voice_'): found['voice'] = path\n                    elif path.name.startswith('bg_'): found['bg'] = path\n                if set(found) != {'voice', 'bg'} or not all(p.is_file() for p in found.values()):\n                    raise RuntimeError('لم يُنتج نموذج الفصل مساري الصوت والمحيط')\n                voices.append(found['voice']); backgrounds.append(found['bg'])\n            finally:\n                raw.unlink(missing_ok=True)\n        outputs = []\n        for label, parts in (('voice', voices), ('background', backgrounds)):\n            listing = work/f'{label}_list.txt'\n            listing.write_text(''.join(\"file '\"+str(p)+\"'\\n\" for p in parts))\n            target = work/f'{label}.m4a'\n            print('جمع ' + ('مسار الكلام' if label == 'voice' else 'مسار المحيط') + '…', flush=True)\n            ffmpeg(['-f', 'concat', '-safe', '0', '-i', listing, '-c:a', 'aac', '-b:a', '192k', '-movflags', '+faststart', target])\n            outputs.append(target)\n        # Free the separation model before anything else uses the GPU (speech-to-text).\n        separator = None\n        gc.collect()\n        if extra:\n            outputs += list(extra(outputs[0], work) or [])\n        bundle = work/'dub.zip'\n        with zipfile.ZipFile(bundle, 'w', zipfile.ZIP_STORED) as z:\n            for path in outputs:\n                z.write(path, path.name)\n        print('اكتمل تجهيز الدبلجة:', round(bundle.stat().st_size/1024**2, 1), 'MB', flush=True)\n        return bundle\n    finally:\n        del separator\n        gc.collect()\n";
export const downloadSource="\"\"\"Public media URLs only; runs on the user's Colab session, no account cookies.\"\"\"\nimport ipaddress, re, shutil, socket, subprocess, sys, threading, time, hashlib, tarfile, io, urllib.request, json\nfrom pathlib import Path\nfrom urllib.parse import urlsplit\n\nHOSTS = {'youtube.com','youtu.be','tiktok.com','x.com','twitter.com','instagram.com','snapchat.com','facebook.com','fb.watch','fb.com','vimeo.com','reddit.com','redd.it','pinterest.com','pin.it','dailymotion.com','dai.ly','twitch.tv'}\nLIMIT = 256*1024**2\n\n\ndef public_url(value):\n    u = urlsplit(value)\n    if u.scheme != 'https' or not any(u.hostname==h or (u.hostname or '').endswith('.'+h) for h in HOSTS) or u.username or u.password or u.port not in (None,443) or u.path in ('','/') or len(value)>2000:\n        raise ValueError('رابط المقطع غير مدعوم؛ استخدم رابطًا عامًا من المنصات المحددة')\n    return value\n\n\ndef public_dns(original):\n    def resolve(host, port, *args, **kwargs):\n        rows = original(host, port, *args, **kwargs)\n        if not rows or any(not ipaddress.ip_address(row[4][0].split('%')[0]).is_global for row in rows):\n            raise ValueError('رُفض اتصال التحميل بعنوان شبكة غير عام')\n        return rows\n    return resolve\n\n_READY=False\n\ndef javascript_runtime(root,report):\n node=shutil.which('node')\n if node:\n  try:\n   version=subprocess.check_output([node,'--version'],text=True,timeout=10)\n   if int(version.lstrip('v').split('.')[0])>=22:return node\n  except Exception:pass\n cache=Path(__file__).parent/'cache/js';cache.mkdir(parents=True,exist_ok=True);node=cache/'node'\n if node.is_file():return str(node)\n report('setup','تجهيز JavaScript المتوافق ليوتيوب؛ مرة واحدة للجلسة')\n name='node-v22.21.1-linux-x64';base='https://nodejs.org/dist/v22.21.1/'\n def fetch(name,limit):\n  with urllib.request.urlopen(base+name,timeout=60) as r:data=r.read(limit+1)\n  if len(data)>limit:raise ValueError('تجاوز تنزيل محرك JavaScript الحد')\n  return data\n archive=name+'.tar.xz';checks=fetch('SHASUMS256.txt',100000).decode();expected=next(line.split()[0] for line in checks.splitlines() if line.split()[-1]==archive);data=fetch(archive,60000000)\n if hashlib.sha256(data).hexdigest()!=expected:raise ValueError('فشل التحقق من محرك JavaScript · JS_CHECKSUM')\n with tarfile.open(fileobj=io.BytesIO(data),mode='r:xz') as tar:\n  member=tar.getmember(name+'/bin/node')\n  if not member.isfile() or member.size>150000000:raise ValueError('ملف JavaScript غير صالح')\n  temp=node.with_suffix('.tmp');temp.write_bytes(tar.extractfile(member).read())\n temp.chmod(0o700);temp.replace(node);return str(node)\n\ndef download_error(exc):\n text=str(exc).lower()\n if any(x in text for x in ['not a bot','confirm you’re','confirm you are','sign in to confirm']):return 'المنصة تطلب تحققًا من اتصال Colab؛ المقطع ليس بالضرورة خاصًا. جرّب التحميل من تطبيق مدار على جهازك · PLATFORM_VERIFICATION'\n if any(x in text for x in ['private video','login required','log in','cookies are needed']):return 'هذا الرابط يحتاج تسجيل دخول إلى المنصة · LOGIN_REQUIRED'\n if 'drm' in text:return 'المقطع محمي بـ DRM ولا يمكن تنزيله بهذه الأداة · DRM'\n if any(x in text for x in ['javascript','js runtime','challenge','ejs']):return 'تعذر محرك JavaScript الخاص بالمنصة؛ أعد المحاولة في الجلسة نفسها · JS_CHALLENGE'\n if any(x in text for x in ['403','429','too many requests','forbidden']):return 'رفضت المنصة اتصال الخادم أو حدّت طلباته؛ أعد لاحقًا أو استخدم تطبيق مدار · PLATFORM_NETWORK'\n if any(x in text for x in ['timed out','timeout','network','connection']):return 'تعطل الاتصال بالمنصة؛ أعد المحاولة والجلسة محفوظة · DOWNLOAD_NETWORK'\n if any(x in text for x in ['unsupported','extract','no video formats']):return 'لم يستطع محرك الروابط قراءة هذا المقطع أو صِيغه · EXTRACTOR_FAILED'\n return 'تعذر تنزيل هذا المقطع؛ الجلسة محفوظة ويمكن تجربة رابط آخر · DOWNLOAD_FAILED'\n\n\ndef download_clip(config, root, report):\n    url = public_url(config['url'])\n    report('setup', 'تجهيز أداة التحميل في جلسة Colab')\n    global _READY\n    if not _READY:\n        subprocess.run([sys.executable,'-m','pip','install','--quiet','yt-dlp[default]==2026.10.26'],check=True,timeout=300)\n        _READY=True\n    from yt_dlp import YoutubeDL\n    out = Path(root)/'download'\n    out.mkdir(exist_ok=True)\n    progress_lock=threading.Lock()\n    last_update=[0.0]\n    def progress(data):\n        if data.get('status') == 'downloading':\n            done = data.get('downloaded_bytes') or 0\n            if done > LIMIT: raise ValueError('المقطع يتجاوز حد 256 MB؛ اختر رابط مقطع أقصر')\n            total = data.get('total_bytes') or data.get('total_bytes_estimate') or 0\n            with progress_lock:\n                now=time.monotonic()\n                if now-last_update[0]>=1:\n                    last_update[0]=now\n                    report('downloading', 'تحميل المقطع من المنصة'+(f' · {min(99,round(done/total*100))}٪' if total else '…'))\n    def suitable(info, *, incomplete):\n        if info.get('is_live'): return 'البث المباشر غير مدعوم؛ استخدم مقطعًا مكتملًا'\n    options = dict(outtmpl=str(out/'clip.%(ext)s'), noplaylist=True, max_filesize=LIMIT,\n        format='bestvideo[ext=mp4][vcodec^=avc1][height<=1080]+bestaudio[ext=m4a]/best[ext=mp4][vcodec^=avc1][height<=1080]/bestvideo[ext=mp4][height<=1080]+bestaudio[ext=m4a]/best[ext=mp4][height<=1080]/best[height<=1080]',\n        playlistend=1,lazy_playlist=True,merge_output_format='mp4', restrictfilenames=True, quiet=True, no_warnings=True,\n        socket_timeout=20, retries=2, fragment_retries=2, concurrent_fragment_downloads=4,\n        hls_prefer_native=True, external_downloader={'default':'native'}, proxy='', geo_bypass=False,\n        enable_file_urls=False,\n        remote_components=[], cachedir=False, progress_hooks=[progress], match_filter=suitable)\n    options['js_runtimes']={'node':{'path':javascript_runtime(root,report)}}\n    original = socket.getaddrinfo\n    socket.getaddrinfo = public_dns(original)\n    try:\n        with YoutubeDL(options) as downloader:\n            info = downloader.extract_info(url, download=False)\n            if not info or info.get('_type') in ('playlist','multi_video'):\n                raise ValueError('استخدم رابط مقطع واحد، وليس حسابًا أو قائمة تشغيل')\n            if info.get('is_live') or info.get('has_drm'): raise ValueError('البث المباشر والمحتوى المحمي غير مدعومين')\n            downloader.process_ie_result(info, download=True)\n    except ValueError: raise\n    except Exception as exc:\n        raise ValueError(download_error(exc)) from exc\n    finally:\n        socket.getaddrinfo = original\n    files = [p for p in out.glob('clip.*') if p.suffix.lower() in ('.mp4','.mkv','.webm','.mov') and p.is_file()]\n    if not files: raise ValueError('لم تُنتج المنصة ملف فيديو قابلًا للتنزيل')\n    source=max(files,key=lambda p:p.stat().st_size)\n    from madar_colab_runtime import prepare_mp4\n    target=prepare_mp4(source,Path(root)/'downloaded.mp4',report)\n    if target.stat().st_size>LIMIT: raise ValueError('الناتج يتجاوز حد تنزيل المتصفح 256 MB')\n    return target\n";
export const cloudSource="\"\"\"Allowlisted media/document jobs. User inputs are data, never Python or shell.\"\"\"\nimport gc, json, re, subprocess, sys, zipfile, ctypes, importlib, importlib.metadata, os, time, threading, queue, shutil\nfrom pathlib import Path\nsys.path.insert(0,str(Path(__file__).resolve().parent))\n\nDEPS={\n 'ocr':['easyocr==1.7.2','pypdfium2==5.15.2'],\n 'cutout':['rembg[gpu]==2.0.67','onnxruntime-gpu[cuda,cudnn]==1.23.2'],\n 'word':['pdf2docx==0.5.13','pypdfium2==5.15.2'],\n 'asr':['ctranslate2==4.6.0','onnxruntime-gpu[cuda,cudnn]==1.23.2','av==16.0.1','tokenizers==0.21.4','huggingface-hub==0.36.0','nvidia-cublas-cu12>=12,<13','nvidia-cudnn-cu12>=9,<10'],\n 'translate':['transformers==4.51.3','sentencepiece==0.2.3','accelerate==1.6.0'],\n 'burn':[], 'convert':[], 'resize':[],\n 'imagegen':['diffusers==0.35.1','transformers==4.51.3','accelerate==1.6.0','sentencepiece==0.2.3'],\n 'videogen':['diffusers==0.35.1','transformers==4.51.3','accelerate==1.6.0','sentencepiece==0.2.3','ftfy==6.3.1','imageio[ffmpeg]==2.37.0']}\n# Install the full ASR/translation stack before importing any ML package.\nDEPS['asr']=[*DEPS['asr'],*DEPS['translate']]\n\nLANG={'ar':'arb_Arab','en':'eng_Latn','ja':'jpn_Jpan','fr':'fra_Latn','es':'spa_Latn','de':'deu_Latn','tr':'tur_Latn'}\n\n\ndef cuda():\n import torch\n if not torch.cuda.is_available(): raise ValueError('هذه الأداة تحتاج GPU فعليًا؛ اختر T4 أو L4 أو A100 ثم أعد المحاولة')\n return torch\n\n\n_INSTALLED=set()\n_MODELS={}\n\ndef release_models():\n stop_translator();_MODELS.clear();gc.collect()\n torch=sys.modules.get('torch')\n if torch and torch.cuda.is_available():torch.cuda.empty_cache()\n\ndef cached_model(key,loader,report):\n if key not in _MODELS:\n  release_models();_MODELS[key]=loader()\n else:report('processing','النموذج جاهز في ذاكرة الجلسة؛ بدء المعالجة مباشرة')\n return _MODELS[key]\n\ndef install(task, report):\n if task in _INSTALLED:return\n report('setup','فحص مكتبات الأداة؛ تُجهّز مرة واحدة داخل هذه الجلسة')\n constraints=Path(__file__).parent/'constraints.txt'\n constraints.write_text('numpy==2.2.6\\nnumba==0.61.2\\nonnxruntime-gpu==1.23.2\\nhuggingface-hub==0.36.0\\ntokenizers==0.21.4\\nopencv-python-headless==4.11.0.86\\n')\n deps=DEPS[task]\n if deps:\n  try:\n   from madar_colab_runtime import install_once\n   commands=[['install','--quiet','--disable-pip-version-check','-c',str(constraints),*deps]]\n   if task=='asr':commands.append(['install','--quiet','--no-deps','faster-whisper==1.2.1'])\n   install_once('task-'+task,commands)\n  except subprocess.TimeoutExpired:raise ValueError('انتهت مهلة تجهيز المكتبات؛ يمكن إعادة المحاولة بنفس الجلسة · DEPENDENCY_TIMEOUT')\n  except subprocess.CalledProcessError:raise ValueError('تعذر تثبيت مكتبات الأداة المتوافقة · DEPENDENCY_INSTALL')\n importlib.invalidate_caches();_INSTALLED.add(task)\n\ndef load_model(loader,report):\n # Retry only known transfer failures. Hugging Face reuses verified cached files.\n for attempt in range(3):\n  try:return loader()\n  except Exception as exc:\n   code=type(exc).__name__;text=str(exc).lower()\n   transient=code in {'ReadTimeout','ConnectTimeout','Timeout','ConnectionError','LocalEntryNotFoundError'} or any(x in text for x in ['timed out','connection reset','temporarily unavailable','502 bad gateway','503 service unavailable','504 gateway'])\n   if not transient or attempt==2:raise\n   report('processing',f'تأخر تنزيل النموذج؛ استكمال التنزيل المحفوظ · {attempt+1}/2')\n   time.sleep(attempt+1)\n\n\ndef transcribe_transformers(source,cfg,root,report):\n install('translate',report)\n torch=cuda()\n from transformers import AutoModelForSpeechSeq2Seq,AutoProcessor,pipeline\n name='openai/whisper-large-v3-turbo'\n report('processing','تشغيل Whisper على PyTorch GPU كمسار توافق بديل')\n def loader():\n  model=load_model(lambda:AutoModelForSpeechSeq2Seq.from_pretrained(name,torch_dtype=torch.float16,low_cpu_mem_usage=True,use_safetensors=True,trust_remote_code=False).to('cuda'),report)\n  processor=load_model(lambda:AutoProcessor.from_pretrained(name,trust_remote_code=False),report)\n  return pipeline('automatic-speech-recognition',model=model,tokenizer=processor.tokenizer,feature_extractor=processor.feature_extractor,chunk_length_s=30,batch_size=1,torch_dtype=torch.float16,device='cuda:0')\n pipe=cached_model('whisper-pytorch',loader,report);kwargs={'task':'transcribe'}\n if cfg['language']!='auto':kwargs['language']=cfg['language']\n out=pipe(str(source),return_timestamps=True,generate_kwargs=kwargs)\n cues=[]\n for i,chunk in enumerate(out.get('chunks',[]),1):\n  start,end=chunk.get('timestamp',(None,None));text=chunk.get('text','').strip()\n  if not text:continue\n  if start is None or end is None or end<=start:raise ValueError('تعذر استنتاج توقيت بعض الجمل؛ أعد التفريغ بلغة محددة · ASR_TIMESTAMPS')\n  cues.append(f'{i}\\n{timestamp(start)} --> {timestamp(end)}\\n{text}\\n')\n if not cues:raise ValueError('لم يُكتشف كلام واضح مع توقيت صالح · ASR_NO_SPEECH')\n (root/'original.srt').write_text('\\n'.join(cues),encoding='utf-8');(root/'transcript.txt').write_text(out.get('text',''),encoding='utf-8')\n (root/'language.json').write_text(json.dumps({'language':cfg['language']}),encoding='utf-8')\n return zip_outputs(root,[root/'original.srt',root/'transcript.txt'])\n\n\ndef preload_cuda():\n # CTranslate2 also needs its libraries loaded before import, not just an ORT provider.\n import site\n for folder in site.getsitepackages():\n  for library in ['nvidia/cublas/lib/libcublasLt.so.12','nvidia/cublas/lib/libcublas.so.12','nvidia/cudnn/lib/libcudnn.so.9']:\n   p=Path(folder)/library\n   if p.exists():ctypes.CDLL(str(p),mode=ctypes.RTLD_GLOBAL)\n\n\ndef run_ffmpeg(args):\n subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-y','-protocol_whitelist','file,pipe',*map(str,args)],check=True,timeout=1800)\n\n\ndef ensure_image(source):\n from PIL import Image, ImageOps\n Image.MAX_IMAGE_PIXELS=24000000\n image=Image.open(source)\n if image.width*image.height>24000000:raise ValueError('الصورة تتجاوز 24 مليون بكسل')\n return ImageOps.exif_transpose(image).convert('RGB')\n\n\ndef zip_outputs(root, names):\n out=root/'results.zip'\n with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:\n  for path in names:z.write(path,Path(path).name)\n return out\n\n\ndef timestamp(seconds):\n ms=max(0,round(float(seconds)*1000));h,ms=divmod(ms,3600000);m,ms=divmod(ms,60000);s,ms=divmod(ms,1000)\n return f'{h:02}:{m:02}:{s:02},{ms:03}'\n\n\ndef load_nllb_weights(name,revision,device='cuda'):\n import torch\n from transformers import AutoConfig,AutoModelForSeq2SeqLM\n from transformers.utils.hub import cached_file\n from safetensors import safe_open\n from safetensors.torch import load_file\n # Restore safetensors alias metadata before tying shared embeddings. Strict\n # loading rejects missing weights; allocating empty tensors is never a fix.\n weights_path=cached_file(name,'model.safetensors',revision=revision)\n state=load_file(weights_path,device='cpu')\n with safe_open(weights_path,framework='pt',device='cpu') as checkpoint:aliases=checkpoint.metadata() or {}\n for alias,target in aliases.items():\n  if alias!='format' and alias not in state and target in state:state[alias]=state[target]\n config=AutoConfig.from_pretrained(name,revision=revision,trust_remote_code=False)\n dtype=torch.float16 if device=='cuda' else torch.float32\n with torch.device('cpu'):model=AutoModelForSeq2SeqLM.from_config(config,torch_dtype=dtype,trust_remote_code=False)\n model.load_state_dict(state,strict=True);del state\n model.tie_weights()\n if any(p.is_meta for p in model.parameters()) or any(p.is_meta for p in model.buffers()):raise ValueError('لم تُحمّل أوزان الترجمة كاملة؛ رُفض تشغيل نموذج بأوزان فارغة · MODEL_META_TENSOR')\n return model.eval().to(device)\n\n\n_TRANSLATOR=None\nclass TranslationWorkerError(RuntimeError):\n def __init__(self,payload):super().__init__(payload.get('message','تعذر محرك الترجمة'));self.worker_diagnostic=payload\n\n\ndef stop_translator():\n global _TRANSLATOR\n child=_TRANSLATOR;_TRANSLATOR=None\n if not child:return\n p=child['process']\n try:\n  p.stdin.close();p.wait(timeout=3)\n except (OSError,subprocess.TimeoutExpired):\n  p.terminate()\n  try:p.wait(timeout=3)\n  except subprocess.TimeoutExpired:p.kill();p.wait(timeout=3)\n child['log'].close()\n\n\ndef translation_worker():\n global _TRANSLATOR\n if _TRANSLATOR and _TRANSLATOR['process'].poll() is None:return _TRANSLATOR\n stop_translator();env=os.environ.copy();env.update(USE_TF='0',USE_FLAX='0',TOKENIZERS_PARALLELISM='false')\n log=open(Path(__file__).parent/'translation-worker.log','a')\n try:p=subprocess.Popen([sys.executable,'-u',str(Path(__file__).resolve()),'--translation-worker'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=log,text=True,encoding='utf-8',bufsize=1,env=env)\n except BaseException:log.close();raise\n events=queue.Queue(maxsize=100)\n def reader():\n  try:\n   for line in iter(p.stdout.readline,''):\n    if len(line)>8*1024**2:events.put({'event':'protocol-error'});return\n    try:message=json.loads(line)\n    except ValueError:continue\n    try:events.put(message,timeout=1)\n    except queue.Full:return\n  finally:\n   try:events.put_nowait({'event':'closed'})\n   except queue.Full:pass\n threading.Thread(target=reader,daemon=True).start();_TRANSLATOR={'process':p,'events':events,'log':log};return _TRANSLATOR\n\n\ndef translate_lines(lines,source,target,report,names=None):\n if source not in LANG or target not in LANG:raise ValueError('لغة ترجمة غير مدعومة')\n # A fresh interpreter sees the installed stack, not stale lazy imports from ASR.\n # It remains warm for later translations and is released before other GPU models.\n if _MODELS:release_models()\n child=translation_worker();p=child['process']\n p.stdin.write(json.dumps({'lines':lines,'source':source,'target':target,'names':names or {}},ensure_ascii=False)+'\\n');p.stdin.flush();deadline=time.monotonic()+1200\n while time.monotonic()<deadline:\n  try:event=child['events'].get(timeout=5)\n  except queue.Empty:\n   if p.poll() is not None:break\n   continue\n  if event.get('event')=='progress':report('processing',event.get('message','تشغيل محرك الترجمة'));continue\n  if event.get('event')=='result':\n   result=event.get('lines')\n   if not isinstance(result,list) or len(result)!=len(lines) or any(not isinstance(t,str) for t in result):stop_translator();raise ValueError('رد ترجمة غير مكتمل؛ لم يُعتمد الناتج')\n   return result\n  if event.get('event')=='error':raise TranslationWorkerError(event)\n  if event.get('event') in {'closed','protocol-error'}:break\n stop_translator();raise ValueError('توقف محرك الترجمة المنفصل أو انتهت مهلته؛ المصدر محفوظ · TRANSLATION_WORKER_STOPPED')\n\n\ndef _translate_lines_local(lines, source, target, report, names=None,device='cuda'):\n if device=='cuda':torch=cuda()\n else:import torch\n from transformers import AutoTokenizer, AutoModelForSeq2SeqLM\n report('processing','تحميل نموذج الترجمة NLLB إلى GPU')\n if tuple(int(v) for v in torch.__version__.split('.')[:2]) < (2,6):raise ValueError('نموذج الترجمة يحتاج PyTorch 2.6 أو أحدث لتحميل الأوزان بأمان')\n name='facebook/nllb-200-distilled-600M';revision='38bd1c6a0f58097b26ef7c7cd73a0dcac034350a'\n def loader():\n  tok=load_model(lambda:AutoTokenizer.from_pretrained(name,revision=revision,src_lang=LANG[source],trust_remote_code=False),report)\n  model=load_model(lambda:load_nllb_weights(name,revision,device),report)\n  return tok,model\n tok,model=cached_model('nllb',loader,report);tok.src_lang=LANG[source]\n\n try:\n  result=[]\n  names=names or {}\n  pattern='('+'|'.join(re.escape(k) for k in sorted(names,key=len,reverse=True))+')' if names else None\n  for i,line in enumerate(lines):\n   if not line.strip() or '-->' in line or line.strip().isdigit() or line.strip()=='WEBVTT':result.append(line);continue\n   segments=re.split(pattern,line) if pattern else [line]\n   blocks=[piece if piece in names else sub for piece in segments for sub in ([piece] if piece in names else [piece[j:j+400] for j in range(0,len(piece),400)])];out=[]\n   for block in blocks:\n    if block in names:out.append(names[block]);continue\n    if not block.strip():continue\n    inp=tok(block,return_tensors='pt',truncation=True,max_length=512).to(device)\n    with torch.inference_mode():tokens=model.generate(**inp,forced_bos_token_id=tok.convert_tokens_to_ids(LANG[target]),max_new_tokens=512)\n    out.append(tok.batch_decode(tokens,skip_special_tokens=True)[0])\n   result.append(' '.join(out));report('processing',f'ترجمة النص · {i+1}/{len(lines)} سطرًا؛ التوقيت محفوظ')\n  return result\n finally:gc.collect()\n\n\ndef english_prompt(prompt,report):\n if re.search('[\\u0600-\\u06ff]',prompt):return translate_lines([prompt],'ar','en',report)[0]\n return prompt\n\n\ndef safety_components(device='cuda',dtype=None):\n import torch\n from diffusers.pipelines.stable_diffusion.safety_checker import StableDiffusionSafetyChecker\n from transformers import CLIPImageProcessor\n checker,loading=StableDiffusionSafetyChecker.from_pretrained('CompVis/stable-diffusion-safety-checker',torch_dtype=dtype or torch.float16,output_loading_info=True)\n if loading.get('missing_keys') or loading.get('mismatched_keys') or loading.get('error_msgs'):raise ValueError('لم تُحمّل أوزان فحص المحتوى كاملة؛ لم يُسلّم الناتج · CONTENT_REVIEW_ERROR')\n if any(p.is_meta for p in checker.parameters()) or any(p.is_meta for p in checker.buffers()):raise ValueError('أوزان فحص المحتوى غير جاهزة؛ لم يُسلّم الناتج · CONTENT_REVIEW_ERROR')\n checker=checker.eval().to(device)\n processor=CLIPImageProcessor.from_pretrained('CompVis/stable-diffusion-safety-checker')\n return checker,processor\n\n\n# Dedicated visual classifier for generated video. CompVis can reject even a\n# constant RGB frame; do not use its image-generation concept embeddings here.\nVIDEO_REVIEW_MODEL='Falconsai/nsfw_image_detection'\nVIDEO_REVIEW_REVISION='96cb0d0342c7afb80cab76ecc58b265fa44da256'\n\ndef video_content_flags(logits,labels):\n import torch\n labels={int(k):str(v).lower() for k,v in labels.items()}\n if set(labels)!={0,1} or set(labels.values())!={'normal','nsfw'}:raise ValueError('فئات نموذج فحص الفيديو غير مطابقة؛ لم يُسلّم الناتج · CONTENT_REVIEW_ERROR')\n if logits.ndim!=2 or logits.shape[1]!=2 or not bool(torch.isfinite(logits).all()):raise ValueError('نتيجة مصنّف الفيديو غير صالحة؛ لم يُسلّم الناتج · CONTENT_REVIEW_ERROR')\n nsfw=next(k for k,v in labels.items() if v=='nsfw')\n # Standard binary decision; uncertain ties are blocked too.\n return (logits.float().softmax(dim=-1)[:,nsfw]>=0.5).cpu().tolist()\n\n\ndef video_safety_components(device='cuda'):\n import torch\n from transformers import AutoImageProcessor,AutoModelForImageClassification\n model,loading=AutoModelForImageClassification.from_pretrained(VIDEO_REVIEW_MODEL,revision=VIDEO_REVIEW_REVISION,torch_dtype=torch.float32,use_safetensors=True,trust_remote_code=False,output_loading_info=True)\n if loading.get('missing_keys') or loading.get('mismatched_keys') or loading.get('error_msgs') or any(p.is_meta for p in model.parameters()) or any(p.is_meta for p in model.buffers()):raise ValueError('لم تُحمّل أوزان فحص الفيديو كاملة؛ لم يُسلّم الناتج · CONTENT_REVIEW_ERROR')\n model=model.eval().to(device)\n processor=AutoImageProcessor.from_pretrained(VIDEO_REVIEW_MODEL,revision=VIDEO_REVIEW_REVISION,trust_remote_code=False,use_fast=False)\n def checker(images,clip_input):\n  return images,video_content_flags(model(pixel_values=clip_input).logits,model.config.id2label)\n return checker,processor\n\n\ndef video_scene_conditioning(original,translated):\n # Preserve the requested action/place; make clothing explicit for child scenes.\n child_en=re.search(r'\\b(?:boy|girl|child|children|kid|kids|toddler|baby|teenager)\\b',translated,re.I)\n child_ar=re.search(r'(?<!\\w)(?:ال)?(?:ولد|طفل|طفلة|[أا]طفال|صبي|بنت|فتى|فتاة صغيرة)(?!\\w)',original)\n prompt=translated.strip()\n if child_en or child_ar:\n  beach=re.search(r'\\b(?:beach|shore|seaside|coast)\\b',translated,re.I) or re.search(r'شاط|ساحل',original)\n  if beach:prompt+=' The child is wearing a loose long-sleeved shirt, long trousers and sneakers throughout the scene. Wide camera framing keeps the complete outfit visible.'\n  else:prompt+=' The child is fully clothed in clothing appropriate to the described setting and time period.'\n negative='nudity, naked, shirtless, bare chest, underwear, sexual content'\n return prompt,negative\n\n\nclass ContentReviewRequired(ValueError):\n def __init__(self,message,review_details=None):\n  super().__init__(message);self.review_details=review_details or {}\n\n\ndef review_video_frames(frames,report):\n import numpy as np\n torch=cuda()\n if not frames:raise ValueError('لم ينتج النموذج إطارات صالحة للفحص · CONTENT_REVIEW_ERROR')\n report('processing','اكتمل توليد اللقطة؛ جارٍ فحص المحتوى قبل التصدير')\n # Use the pinned dedicated classifier in full precision for every frame.\n checker,processor=video_safety_components()\n for start in range(0,len(frames),4):\n  batch=[frame.convert('RGB') for frame in frames[start:start+4]]\n  pixels=processor(images=batch,return_tensors='pt').pixel_values.to('cuda',dtype=torch.float32)\n  with torch.inference_mode():_,flags=checker(images=np.stack([np.asarray(frame,dtype=np.float32)/255.0 for frame in batch]),clip_input=pixels)\n  if not isinstance(flags,(list,tuple)) or len(flags)!=len(batch) or not all(isinstance(flag,(bool,np.bool_)) for flag in flags):raise ValueError('لم يكتمل فحص جميع إطارات اللقطة؛ لم يُسلّم ناتج غير مفحوص · CONTENT_REVIEW_ERROR')\n  if any(flags):\n   first=start+next(i for i,flag in enumerate(flags) if flag)\n   details={'firstFlaggedFrame':first+1,'timestampMs':round(first*1000/16),'checkedFrames':start+len(batch),'totalFrames':len(frames),'fps':16,'checker':VIDEO_REVIEW_MODEL,'revision':VIDEO_REVIEW_REVISION}\n   raise ContentReviewRequired('اكتمل التوليد؛ أوقف مصنّف المحتوى تسليم اللقطة. هذا القرار يخص الإطارات الناتجة ولا يثبت وجود مشكلة في وصفك · CONTENT_REVIEW_REQUIRED',details)\n  report('processing',f'فحص اللقطة قبل التصدير · {min(start+4,len(frames))}/{len(frames)} إطارًا')\n return True\n\n\ndef check_video_text_dependencies():\n # Exercise the real installed pipeline text path before downloading weights.\n try:\n  import ftfy\n  from diffusers.pipelines.wan.pipeline_wan import prompt_clean\n  cleaned=prompt_clean('  Madar &amp; video  ')\n  if cleaned!='Madar & video':raise ValueError('unexpected text preprocessing result')\n except (ImportError,NameError,AttributeError,ValueError) as exc:\n  raise ValueError('تعذر تجهيز مكتبة تهيئة وصف الفيديو؛ أعد المحاولة لتجهيز المتطلبات · VIDEOGEN_TEXT_SETUP') from exc\n\n\ndef process(task, source, cfg, root, report):\n if task=='asr' and not cfg.get('_basic_asr'):return caption_workflow(source,cfg,root,report)\n install(task,report)\n if task=='ocr':\n  cuda();import easyocr;import numpy as np\n  report('processing','تحميل نموذج OCR واستخراج النص')\n  reader=cached_model('ocr-'+cfg['language'],lambda:easyocr.Reader({'ar':['ar','en'],'en':['en'],'ja':['ja','en']}[cfg['language']],gpu=True),report)\n  def text(image):return '\\n'.join(reader.readtext(np.asarray(image.convert('RGB')),detail=0,paragraph=True))\n  if cfg['ext']=='pdf':\n   import pypdfium2 as pdfium\n   doc=pdfium.PdfDocument(str(source))\n   if len(doc)>20:raise ValueError('اختر PDF حتى 20 صفحة؛ قسّم الملف من أداة ترتيب PDF')\n   pages=[]\n   try:\n    for i in range(len(doc)):\n     page=doc[i]\n     width,height=page.get_size()\n     if width*height*1.8**2>24000000:raise ValueError('صفحة PDF تتجاوز حد الصورة الآمن؛ قلّل مقاسها أولًا')\n     bitmap=page.render(scale=1.8);image=bitmap.to_pil();pages.append(f'— الصفحة {i+1} —\\n'+text(image));bitmap.close();page.close();report('processing',f'OCR · الصفحة {i+1}/{len(doc)}')\n   finally:doc.close()\n   content='\\n\\n'.join(pages)\n  else:content=text(ensure_image(source))\n  if not content.strip():raise ValueError('لم يُكتشف نص واضح؛ جرّب صورة أوضح')\n  out=root/'ocr.txt';out.write_text(content,encoding='utf-8');return out\n if task=='cutout':\n  cuda();preload_cuda();import onnxruntime as ort\n  if hasattr(ort,'preload_dlls'):ort.preload_dlls(directory='')\n  from rembg import new_session, remove\n  report('processing','تحميل نموذج العزل واختبار مزود CUDA')\n  session=cached_model('cutout',lambda:new_session('isnet-general-use',providers=['CUDAExecutionProvider']),report)\n  if 'CUDAExecutionProvider' not in session.inner_session.get_providers():raise ValueError('لم يتفعّل CUDA لمحرك العزل؛ لم يبدأ تنفيذ على CPU')\n  image=ensure_image(source);result=remove(image,session=session);out=root/'cutout.png';result.save(out);return out\n if task=='word':\n  import pypdfium2 as pdfium\n  doc=pdfium.PdfDocument(str(source));count=len(doc);doc.close()\n  if count>20:raise ValueError('تحويل Word حتى 20 صفحة للعملية؛ قسّم المستند أولًا')\n  from pdf2docx import Converter\n  report('processing','إعادة بناء النصوص والصور والجداول في Word')\n  out=root/'converted.docx';converter=Converter(str(source))\n  try:converter.convert(str(out),start=0,end=count,multi_processing=False)\n  finally:converter.close()\n  return out\n if task=='asr':\n  cuda();report('processing','تجهيز الصوت واختبار محرك Whisper على CUDA')\n  try:\n   preload_cuda();import onnxruntime as ort\n   if hasattr(ort,'preload_dlls'):ort.preload_dlls(directory='')\n   from faster_whisper import WhisperModel\n   import ctranslate2\n   supported=ctranslate2.get_supported_compute_types('cuda');compute=next((v for v in ['float16','int8_float16','float32'] if v in supported),None)\n   if not compute:raise RuntimeError('CUDA_COMPUTE_UNSUPPORTED')\n   model=cached_model('whisper-'+compute,lambda:load_model(lambda:WhisperModel('large-v3-turbo',device='cuda',compute_type=compute),report),report)\n   def decode(vad):\n    segments,info=model.transcribe(str(source),language=None if cfg['language']=='auto' else cfg['language'],vad_filter=vad,beam_size=5)\n    text=[];srt=[]\n    for i,seg in enumerate(segments,1):\n     text.append(seg.text.strip());srt.append(f'{i}\\n{timestamp(seg.start)} --> {timestamp(seg.end)}\\n{seg.text.strip()}\\n');report('processing',f'تفريغ الكلام · وصلنا إلى {round(seg.end/60,1)} دقيقة')\n    return text,srt,info\n   try:text,srt,info=decode(True)\n   except Exception as exc:\n    if not any(x in (type(exc).__module__+' '+str(exc)).lower() for x in ['onnxruntime','silero','vad']):raise\n    report('processing','تعذر مرشح الصمت؛ استكمال التفريغ بنفس النموذج دون المرشح');text,srt,info=decode(False)\n  except (RuntimeError,OSError,ImportError,ValueError) as exc:\n   if not any(x in str(exc).lower() for x in ['cuda','cudnn','cublas','ctranslate','onnxruntime','undefined symbol','compute type']):raise\n   if 'out of memory' in str(exc).lower():raise\n   model=None;release_models();return transcribe_transformers(source,cfg,root,report)\n  if not text:raise ValueError('لم يُكتشف كلام واضح في الملف · ASR_NO_SPEECH')\n  (root/'language.json').write_text(json.dumps({'language':info.language}),encoding='utf-8')\n  txt=root/'transcript.txt';sub=root/'original.srt';txt.write_text('\\n'.join(text),encoding='utf-8');sub.write_text('\\n'.join(srt),encoding='utf-8');return zip_outputs(root,[txt,sub])\n if task=='translate':\n  text=source.read_text(encoding='utf-8-sig')\n  if len(text)>200000:raise ValueError('النص أطول من الحد 200 ألف حرف')\n  names={}\n  for row in cfg.get('names','').splitlines()[:30]:\n   key,_,value=row.partition('=');key=key.strip();value=value.strip() or key\n   if key:names[key]=value\n  translated='\\n'.join(translate_lines(text.splitlines(),cfg['source'],cfg['target'],report,names))\n  out=root/('translated.'+cfg['ext']);original=root/('original.'+cfg['ext']);out.write_text(translated,encoding='utf-8');original.write_text(text,encoding='utf-8');return zip_outputs(root,[original,out])\n if task in {'burn','convert','resize'}:\n  from madar_colab_runtime import video_encoder, nvenc_ready\n  import madar_colab_runtime as media_runtime\n  out=root/('result.'+(cfg.get('format','mp4')));report('processing','فحص قدرات الفيديو وتجهيز الناتج')\n  if task=='convert':\n   media_runtime.export_media(source,out,quality=cfg['quality']);return out\n  codec=video_encoder();report('processing','ترميز الفيديو على GPU · NVENC' if 'h264_nvenc' in codec else 'ترميز CPU لهذا الفيديو؛ '+(media_runtime.nvenc_explanation() if hasattr(media_runtime,'nvenc_explanation') else 'لم ينجح اختبار NVENC'))\n  filters=[]\n  if task=='burn':\n   from madar_captions import burn\n   return burn(source,cfg,root,report,codec,run_ffmpeg,subtitle_style)\n  if task=='resize':\n   w,h={'portrait':(720,1280),'landscape':(1280,720),'square':(720,720)}[cfg['ratio']]\n   if cfg['fit']=='stretch':\n    from madar_captions import dimensions\n    sw,sh=dimensions(source);amount=float(cfg.get('stretch','100'))/100\n    if not 0<=amount<=1:raise ValueError('نسبة التمديد غير صالحة')\n    scale=min(w/sw,h/sh);rw=max(2,min(w,round(sw*(scale+(w/sw-scale)*amount)/2)*2));rh=max(2,min(h,round(sh*(scale+(h/sh-scale)*amount)/2)*2))\n    filters=['-vf',f'scale={rw}:{rh},pad={w}:{h}:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1']\n   elif cfg['fit']=='crop':filters=['-vf',f'scale={w}:{h}:force_original_aspect_ratio=increase,crop={w}:{h},setsar=1']\n   else:filters=['-filter_complex',f'[0:v]split=2[bg][fg];[bg]scale={w}:{h}:force_original_aspect_ratio=increase,crop={w}:{h},boxblur=20:2[blur];[fg]scale={w}:{h}:force_original_aspect_ratio=decrease[front];[blur][front]overlay=(W-w)/2:(H-h)/2,setsar=1[v]','-map','[v]','-map','0:a:0?']\n  if task=='convert':\n   q={'high':'20','balanced':'25','small':'30'}[cfg['quality']]\n   codec=[*codec];flag='-cq' if 'h264_nvenc' in codec else '-crf';codec[codec.index(flag)+1]=q\n  args=['-i',source,*filters,*codec,'-c:a','aac','-b:a','160k','-map_metadata','-1','-movflags','+faststart',out]\n  try:run_ffmpeg(args)\n  except subprocess.CalledProcessError:\n   if 'h264_nvenc' not in codec:raise\n   report('processing','تعذر NVENC لهذا الملف؛ استكمال التصدير على CPU')\n   run_ffmpeg(['-i',source,*filters,'-c:v','libx264','-preset','veryfast','-crf','23','-c:a','aac','-b:a','160k','-map_metadata','-1','-movflags','+faststart',out])\n  return out\n if task=='imagegen':\n  torch=cuda();prompt=english_prompt(cfg['prompt'],report)\n  from diffusers import AutoPipelineForText2Image\n  report('processing','تجهيز نموذج الصورة من ذاكرة الجلسة أو تنزيله عند أول استخدام')\n  def load_image():\n   checker,processor=safety_components()\n   return AutoPipelineForText2Image.from_pretrained('stabilityai/sd-turbo',torch_dtype=torch.float16,variant='fp16',use_safetensors=True,safety_checker=checker,feature_extractor=processor).to('cuda')\n  pipe=cached_model('sd-turbo',load_image,report)\n  result=pipe(prompt=prompt,num_inference_steps=4,guidance_scale=0.0,width=512,height=512)\n  if result.nsfw_content_detected and any(result.nsfw_content_detected):raise ValueError('تعذر تسليم الصورة وفق فحص سلامة المحتوى؛ عدّل الوصف')\n  out=root/'generated.png';result.images[0].save(out);return out\n if task=='videogen':\n  report('setup','فحص مكتبات تهيئة وصف الفيديو قبل تحميل النموذج');check_video_text_dependencies()\n  torch=cuda()\n  if torch.cuda.get_device_capability()[0]<8:raise ValueError('توليد الفيديو يحتاج L4 أو A100؛ T4 غير مناسب لهذا المسار')\n  prompt=english_prompt(cfg['prompt'],report);prompt,negative_prompt=video_scene_conditioning(cfg['prompt'],prompt);release_models()\n  from diffusers import WanPipeline, AutoencoderKLWan\n  from diffusers.utils import export_to_video\n  release_models();name='Wan-AI/Wan2.1-T2V-1.3B-Diffusers';report('processing','تجهيز نموذج الفيديو؛ الأوزان تُنزّل عند أول استخدام وتبقى في قرص الجلسة')\n  vae=load_model(lambda:AutoencoderKLWan.from_pretrained(name,subfolder='vae',torch_dtype=torch.float32,use_safetensors=True),report)\n  pipe=load_model(lambda:WanPipeline.from_pretrained(name,vae=vae,torch_dtype=torch.bfloat16,use_safetensors=True,low_cpu_mem_usage=True),report);pipe.enable_model_cpu_offload();pipe.vae.enable_tiling()\n  def step(p,i,t,kwargs):report('processing',f'توليد اللقطة · الخطوة {i+1}/25');return kwargs\n  frames=pipe(prompt=prompt,negative_prompt=negative_prompt,width=512,height=288,num_frames={'short':33,'five':81,'eight':129}[cfg['length']],output_type='pil',num_inference_steps=25,guidance_scale=5.0,callback_on_step_end=step).frames[0]\n  del pipe,vae;gc.collect();torch.cuda.empty_cache()\n  review_video_frames(frames,report)\n  report('processing','اكتمل الفحص؛ جارٍ تصدير فيديو MP4')\n  out=root/'generated.mp4';export_to_video(frames,str(out),fps=16);return out\n raise ValueError('نوع أداة غير مدعوم')\n\n# Timed text is always data; style values are mapped to a fixed ASS palette.\ndef subtitle_style(cfg):\n color={'ivory':'&H00C9E7F2','white':'&H00FFFFFF','gold':'&H0078BDD8','black':'&H00223324','mint':'&H00C0E0B0'}[cfg.get('fontColor','ivory')]\n align={'bottom':2,'middle':5,'top':8}[cfg.get('position','bottom')]\n size=int(cfg.get('fontSize','24'))\n if size not in {20,24,32}:raise ValueError('حجم خط غير صالح')\n return f'FontName=DejaVu Sans,FontSize={size},PrimaryColour={color},OutlineColour=&H001A211D,BorderStyle=1,Outline=1.5,Shadow=0,Alignment={align},MarginV=28'\n\n\ndef write_caption_preview(root,srt,language='',original=''):\n data={'srt':srt[:200000],'language':language,'original':original[:200000],'truncated':len(srt)>200000}\n (root/'preview.json').write_text(json.dumps(data,ensure_ascii=False),encoding='utf-8')\n\n\ndef caption_workflow(source,cfg,root,report):\n op=cfg.get('operation','transcribe');original='';language=cfg.get('source','auto')\n if op in {'transcribe','transcribeTranslate','transcribeBurn','transcribeTranslateBurn'}:\n  # Invoke the ordinary fixed ASR path once; follow-up operations reuse its source.\n  reused=False\n  if op in {'transcribeTranslate','transcribeBurn','transcribeTranslateBurn'} and cfg.get('parentJob'):\n   parent=root.parent/cfg['parentJob']\n   try:\n    previous=json.loads((parent/'config.json').read_text())\n    if previous.get('language')==cfg.get('language') and (parent/'language.json').is_file() and '-->' in (parent/'original.srt').read_text(encoding='utf-8'):\n     for filename in ['original.srt','language.json','transcript.txt']:\n      if (parent/filename).is_file():shutil.copyfile(parent/filename,root/filename)\n     reused=True;report('processing','استكمال الترجمة من التفريغ المكتمل؛ لا يُعاد تفريغ المصدر')\n   except (OSError,ValueError):pass\n  if not reused:\n   basic={**cfg,'_basic_asr':True};process('asr',source,basic,root,report)\n  original=(root/'original.srt').read_text(encoding='utf-8');srt=original\n  info=json.loads((root/'language.json').read_text());language=info['language']\n else:srt=cfg['subtitles'];original=srt\n if op in {'transcribeTranslate','transcribeTranslateBurn','translate','translateburn'}:\n  install('translate',report)\n  selected=cfg.get('source','auto');source_language=language if selected=='auto' else selected\n  if selected=='auto' and cfg.get('parentJob'):\n   parent=root.parent/cfg['parentJob'];meta=parent/'language.json'\n   if meta.exists():source_language=json.loads(meta.read_text())['language']\n  if source_language not in LANG:raise ValueError('اختر لغة المصدر صراحة؛ اللغة المكتشفة غير مدعومة للترجمة')\n  if source_language==cfg['target']:raise ValueError('لغة المصدر والهدف متطابقتان؛ اختر لغة أخرى أو احرق التفريغ الأصلي')\n  names={}\n  for row in cfg.get('names','').splitlines()[:30]:\n   key,_,value=row.partition('=');key=key.strip()\n   if key:names[key]=value.strip() or key\n  srt='\\n'.join(translate_lines(srt.splitlines(),source_language,cfg['target'],report,names));language=cfg['target'];(root/'translated.srt').write_text(srt,encoding='utf-8')\n if not (root/'original.srt').exists():(root/'original.srt').write_text(original,encoding='utf-8')\n (root/'rendered.srt').write_text(srt,encoding='utf-8')\n write_caption_preview(root,srt,language,original)\n if op in {'burn','translateburn','transcribeBurn','transcribeTranslateBurn'}:\n  if cfg['ext'] not in {'mp4','mkv','mov','webm','avi','mpeg'}:raise ValueError('دمج الترجمة يحتاج ملف فيديو؛ يمكنك حفظ SRT مع ملف الصوت')\n  return process('burn',source,{**cfg,'subtitles':srt},root,report)\n if not (root/'original.srt').exists():(root/'original.srt').write_text(original,encoding='utf-8')\n outputs=[root/'original.srt'];txt=root/'transcript.txt'\n if txt.exists():outputs.append(txt)\n if (root/'translated.srt').exists():outputs.append(root/'translated.srt')\n return zip_outputs(root,outputs)\n\n\ndef serve_translation_worker(device='cuda'):\n # The Colab allocation outlives Python processes. Exit if the owning worker dies.\n parent=os.getppid()\n def watch_parent():\n  while os.getppid()==parent:time.sleep(2)\n  os._exit(0)\n threading.Thread(target=watch_parent,daemon=True).start()\n def emit(data):print(json.dumps(data,ensure_ascii=False),flush=True)\n for raw in sys.stdin:\n  try:\n   if len(raw)>3*1024**2:raise ValueError('طلب الترجمة أطول من الحد')\n   cfg=json.loads(raw);result=_translate_lines_local(cfg['lines'],cfg['source'],cfg['target'],lambda state,message:emit({'event':'progress','message':message}),cfg.get('names'),device=device)\n   emit({'event':'result','lines':result})\n  except Exception as exc:\n   try:from runner import failure_details\n   except ModuleNotFoundError:from madar_web_job import failure_details\n   code,message,diagnostic=failure_details(exc,{'task':'translate'})\n   emit({'event':'error','code':code,'message':message+' · '+code,'diagnostic':diagnostic})\n\n\nif __name__=='__main__' and sys.argv[1:]==['--translation-worker']:serve_translation_worker()\n\n\n# Small helper models for «دبلج»: who is speaking, and which non-word sounds (laughs, hums…)\n# the performer should make. Both are optional: if either fails the lines are still made.\nSPEAKER_MODEL='microsoft/wavlm-base-plus-sv'\nSOUND_MODEL='MIT/ast-finetuned-audioset-10-10-0.4593'\n# WavLM x-vectors of one voice usually agree above ~0.86, but cartoon voices, effects and leftover\n# music lower that a lot: at 0.82 one person split into several «speakers» (94 lines for a 3 min\n# clip), so pieces join a speaker from 0.72 and a speaker run must last 1.2 s to count.\nSPEAKER_SIMILARITY=0.72\n\n\ndef mono16k(path):\n import numpy as np\n raw=subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-nostdin','-i',str(path),'-ac','1','-ar','16000','-f','f32le','-'],check=True,capture_output=True,timeout=900).stdout\n return np.frombuffer(raw,dtype=np.float32)\n\n\ndef dub_speakers(audio,words,report):\n \"\"\"Labels every word with a speaker number from WavLM voice embeddings of short speech pieces.\"\"\"\n from madar_colab_runtime import speech_units,speech_windows,cluster_speakers,assign_speakers\n torch=cuda()\n from transformers import AutoFeatureExtractor,WavLMForXVector\n report('processing','تمييز صوت كل شخصية')\n extractor=load_model(lambda:AutoFeatureExtractor.from_pretrained(SPEAKER_MODEL,trust_remote_code=False),report)\n model=load_model(lambda:WavLMForXVector.from_pretrained(SPEAKER_MODEL,trust_remote_code=False),report).to('cuda').eval()\n try:\n  units=speech_units(words);windows=speech_windows(words,units);vectors=[]\n  for start in range(0,len(windows),16):\n   clips=[audio[max(0,int(a*16000)):int(b*16000)] for _,a,b in windows[start:start+16]]\n   inputs=extractor(clips,sampling_rate=16000,padding=True,return_attention_mask=True,return_tensors='pt')\n   with torch.no_grad():vectors+=list(model(**{k:v.to('cuda') for k,v in inputs.items()}).embeddings.float().cpu().numpy())\n  labels=cluster_speakers(vectors,SPEAKER_SIMILARITY)\n  assign_speakers(words,units,windows,labels,min_run=1.2)\n  return len({l for l in labels if l is not None})\n finally:\n  del model;gc.collect();torch.cuda.empty_cache()\n\n\ndef dub_sounds(audio,words,report):\n \"\"\"Finds laughs, hums, sighs… on the voice track where Whisper wrote no word, and names them.\"\"\"\n from madar_colab_runtime import sound_regions,name_sound\n regions=sound_regions(audio,16000,words)[:400]\n if not regions:return []\n torch=cuda()\n from transformers import AutoFeatureExtractor,ASTForAudioClassification\n report('processing','البحث عن الضحك والأصوات اللي مو كلام')\n extractor=load_model(lambda:AutoFeatureExtractor.from_pretrained(SOUND_MODEL,trust_remote_code=False),report)\n model=load_model(lambda:ASTForAudioClassification.from_pretrained(SOUND_MODEL,trust_remote_code=False),report).to('cuda').eval()\n try:\n  names=model.config.id2label;found=[]\n  for r in regions:\n   clip=audio[int(r['s']*16000):int(r['e']*16000)]\n   inputs=extractor(clip,sampling_rate=16000,return_tensors='pt')\n   with torch.no_grad():probs=torch.sigmoid(model(**{k:v.to('cuda') for k,v in inputs.items()}).logits[0]).float().cpu().tolist()\n   label=name_sound({names[i]:p for i,p in enumerate(probs)},r['e']-r['s'])\n   if label:found.append({**r,'label':label})\n  return found\n finally:\n  del model;gc.collect();torch.cuda.empty_cache()\n\n\ndef dub_text(voice, target, report):\n \"\"\"Speech-to-text for «دبلج» on the separated voice track, with the time of every word,\n grouped into whole sentences of one speaker; non-word sounds are marked; optionally\n translated to Arabic so the visitor reads while recording.\"\"\"\n from madar_colab_runtime import group_dub_words\n install('asr',report);cuda();report('processing','تفريغ الكلام وتوقيت كل كلمة')\n preload_cuda();import onnxruntime as ort\n if hasattr(ort,'preload_dlls'):ort.preload_dlls(directory='')\n from faster_whisper import WhisperModel\n import ctranslate2\n supported=ctranslate2.get_supported_compute_types('cuda');compute=next((v for v in ['float16','int8_float16','float32'] if v in supported),None)\n if not compute:raise RuntimeError('CUDA_COMPUTE_UNSUPPORTED')\n model=cached_model('whisper-'+compute,lambda:load_model(lambda:WhisperModel('large-v3-turbo',device='cuda',compute_type=compute),report),report)\n segments,info=model.transcribe(str(voice),language=None,vad_filter=True,beam_size=5,word_timestamps=True)\n words=[]\n for i,seg in enumerate(segments):\n  for w in seg.words or []:words.append({'w':w.word,'s':float(w.start),'e':float(w.end),'seg':i})\n  report('processing',f'تفريغ الكلام · وصلنا إلى {round(seg.end/60,1)} دقيقة')\n release_models()\n sounds=[];speakers=0;skipped=[]\n if words:\n  try:audio=mono16k(voice)\n  except Exception:audio=None;skipped.append('audio')\n  if audio is not None:\n   try:speakers=dub_speakers(audio,words,report)\n   except Exception as exc:\n    skipped.append('speakers:'+type(exc).__name__)\n    for w in words:w.pop('spk',None)\n   try:sounds=dub_sounds(audio,words,report)\n   except Exception as exc:skipped.append('sounds:'+type(exc).__name__)\n lines=group_dub_words(words,sounds);lang=info.language;note=''\n if target=='ar' and lines and lang!='ar':\n  if lang in LANG:\n   report('processing','ترجمة الجمل إلى العربية')\n   try:\n    spoken=[l for l in lines if l['say'].strip()]\n    for line,text in zip(spoken,translate_lines([l['say'] for l in spoken],lang,'ar',report)):\n     # Sound marks stay in place: before the sentence if they open it, otherwise after it.\n     marks=[w for w in line['words'] if w.get('k')=='sound'];first=next((w for w in line['words'] if not w.get('k')),None)\n     before=[m['w'] for m in marks if first and m['s']<first['s']];after=[m['w'] for m in marks if not first or m['s']>=first['s']]\n     line['tr']=' '.join([*before,text,*after])\n   finally:stop_translator()\n  else:note='الترجمة للعربي غير متاحة لهذه اللغة؛ يظهر النص بلغته الأصلية'\n release_models()\n if any(x.startswith(('audio','speakers')) for x in skipped):note=(note+' · ' if note else '')+'تمييز الشخصيات ما اشتغل هالمرة؛ الجمل مقسّمة حسب نهايتها'\n return {'language':lang,'target':target,'lines':lines,'note':note,'speakers':speakers,**({'skipped':skipped} if skipped else {})}\n\n\n# Early preparation: started when the Colab session is prepared, while the file is still\n# uploading, so each tool's libraries and model files are ready before the job needs them.\n# It only installs and downloads (no GPU); the job runs exactly as before and simply finds\n# everything in place. Any failure here is ignored: the job then does the same step itself.\nWARM_TOOLS={'separate','dub','asr','translate'}\n\ndef warm(tool):\n if tool not in WARM_TOOLS:return []\n from madar_colab_runtime import install_once,SEPARATION_PIP,MODEL,DUB_MODEL,CACHE\n quiet=lambda *a,**k:None;done=[]\n def step(name,fn):\n  try:fn();done.append(name)\n  except Exception as exc:done.append(name+':'+type(exc).__name__)\n def uvr(model):\n  install_once('separation',SEPARATION_PIP)\n  from audio_separator.separator import Separator\n  CACHE.mkdir(parents=True,exist_ok=True)\n  Separator(model_file_dir=str(CACHE),output_dir=str(CACHE),log_level=40).download_model_files(model)\n def whisper():\n  install('asr',quiet)\n  from faster_whisper.utils import download_model\n  download_model('large-v3-turbo')\n def hub(repo,revision=None,patterns=None):\n  from huggingface_hub import snapshot_download\n  snapshot_download(repo,revision=revision,allow_patterns=patterns)\n if tool in {'separate','dub'}:step('separation',lambda:uvr(DUB_MODEL if tool=='dub' else MODEL))\n if tool in {'dub','asr'}:step('whisper',whisper)\n if tool=='dub':\n  for repo in (SPEAKER_MODEL,SOUND_MODEL):step(repo,lambda repo=repo:hub(repo,patterns=['*.json','*.safetensors','*.bin','*.txt']))\n if tool=='translate':\n  def nllb():\n   install('translate',quiet);hub('facebook/nllb-200-distilled-600M','38bd1c6a0f58097b26ef7c7cd73a0dcac034350a',['*.json','model.safetensors','*.model'])\n  step('nllb',nllb)\n return done\n";
export const serviceSource="\"\"\"Single persistent, fixed-code worker. One job at a time; model/disk cache stays in session.\"\"\"\nimport gc, json, os, signal, subprocess, sys, time, threading\nfrom pathlib import Path\nBASE=Path(__file__).resolve().parent\nVERSION=15\n\ndef atomic(path,data):\n tmp=path.with_suffix('.tmp');tmp.write_text(json.dumps(data,ensure_ascii=False));tmp.replace(path)\n\ndef bootstrap():\n import fcntl\n setup=open(BASE/'bootstrap.lock','a');fcntl.flock(setup,fcntl.LOCK_EX)\n try:\n  health=json.loads((BASE/'service.json').read_text())\n  if time.time()-health.get('heartbeat',0)<30:\n   pid=int(health['pid']);os.kill(pid,0)\n   if health.get('version')==VERSION:return\n   if health.get('activeJob'):raise RuntimeError('WORKER_UPGRADE_BUSY')\n   os.kill(pid,signal.SIGTERM)\n   for _ in range(30):\n    try:os.kill(pid,0)\n    except ProcessLookupError:break\n    time.sleep(.1)\n except (OSError,ValueError,KeyError):pass\n pending=[p.parent for p in (BASE/'jobs').glob('*/ready') if not (p.parent/'started.lock').exists()]\n for root in pending:atomic(root/'state.json',{'state':'setup','message':'بدء عامل الأداة باستخدام Python المثبّت في Colab','updated':time.time()})\n try:\n  subprocess.Popen([sys.executable,'-u',str(BASE/'service.py'),'serve'],cwd=BASE,stdout=open(BASE/'service.log','a'),stderr=subprocess.STDOUT,start_new_session=True)\n except Exception as exc:\n  code='WORKER_LAUNCH_'+type(exc).__name__.upper()\n  for root in pending:atomic(root/'state.json',{'state':'error','message':'تعذر إطلاق عامل الأداة داخل Colab · '+code,'code':code,'updated':time.time()})\n\ndef environment():\n os.environ['USE_TF']='0';os.environ['USE_FLAX']='0';os.environ['HF_HUB_ETAG_TIMEOUT']='60';os.environ['HF_HUB_DOWNLOAD_TIMEOUT']='120';os.environ['TOKENIZERS_PARALLELISM']='false'\n os.environ['HF_HOME']=str(BASE/'cache/huggingface');os.environ['U2NET_HOME']=str(BASE/'cache/rembg');os.environ['XDG_CACHE_HOME']=str(BASE/'cache')\n\ndef warm(tool):\n \"\"\"Installs a tool's libraries and downloads its model files while the file uploads.\n One preparation per tool and session; it never touches the GPU or a job.\"\"\"\n import fcntl\n lock=open(BASE/('warm-'+tool+'.lock'),'a')\n try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n except BlockingIOError:return\n if (BASE/('warm-'+tool+'.json')).exists():return\n environment();sys.path.insert(0,str(BASE))\n started=time.time()\n try:\n  import madar_cloud_tasks\n  done=madar_cloud_tasks.warm(tool)\n except BaseException as exc:done=['failed:'+type(exc).__name__]\n atomic(BASE/('warm-'+tool+'.json'),{'tool':tool,'steps':done,'seconds':round(time.time()-started,1),'finished':time.time()})\n\ndef serve():\n import fcntl\n lock=open(BASE/'service.lock','a')\n try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n except BlockingIOError:return\n environment()\n idle=time.monotonic();last_task=None;health={'version':VERSION,'pid':os.getpid(),'idleMinutes':40,'activeJob':None}\n done=threading.Event()\n def heartbeat():\n  while not done.is_set():\n   try:\n    lease=json.loads((BASE/'lease.json').read_text())\n    if time.time()-float(lease['updated'])>300:\n     atomic(BASE/'service.json',{'version':VERSION,'state':'page-disconnected','heartbeat':time.time()})\n     cloud=sys.modules.get('madar_cloud_tasks')\n     if cloud:cloud.stop_translator()\n     os._exit(0)  # worker only; Google allocation deletion is a separate API request.\n   except (OSError,ValueError,KeyError):pass\n   atomic(BASE/'service.json',{**health,'heartbeat':time.time()});done.wait(5)\n threading.Thread(target=heartbeat,daemon=True).start()\n\n while time.monotonic()-idle<2400:\n  candidates=sorted((BASE/'jobs').glob('*/config.json'),key=lambda p:p.stat().st_mtime)\n  for cfgpath in candidates:\n   root=cfgpath.parent\n   if not (root/'ready').exists() or (root/'started.lock').exists():continue\n   idle=time.monotonic();cfg=json.loads(cfgpath.read_text());task=cfg.get('task','separate')\n   if last_task and last_task!=task:\n    cloud=sys.modules.get('madar_cloud_tasks')\n    if cloud:cloud.release_models()\n    gc.collect()\n   health['activeJob']=root.name\n   import runner\n   runner.ROOT=root\n   try:runner.main()\n   except BaseException:\n    atomic(root/'state.json',{'state':'error','message':'توقف عامل المعالجة؛ أعد المحاولة في الجلسة نفسها · WORKER_FAILED','code':'WORKER_FAILED','updated':time.time()})\n   try:\n    if json.loads((root/'state.json').read_text()).get('state')=='error':\n     cloud=sys.modules.get('madar_cloud_tasks')\n     if cloud:cloud.release_models()\n   except (OSError,ValueError):pass\n   sys.stdout=sys.__stdout__;health['activeJob']=None;last_task=task;idle=time.monotonic()\n  time.sleep(1)\n done.set()\n atomic(BASE/'service.json',{'version':VERSION,'state':'idle-ended','heartbeat':time.time()})\n\nif __name__=='__main__':\n if len(sys.argv)>1 and sys.argv[1]=='serve':serve()\n elif len(sys.argv)>2 and sys.argv[1]=='warm' and sys.argv[2] in {'separate','dub','asr','translate'}:warm(sys.argv[2])\n else:bootstrap()\n";
export const fontSource="FONT_ASSETS={\"DejaVuSans.ttf\":\"\",\"DejaVuSans-Bold.ttf\":\"\",\"Amiri-Regular.ttf\":\"\",\"Amiri-Bold.ttf\":\"\"}\n";
export const captionSource="\"\"\"Fixed-schema ASS text and PNG composition. No user filter expressions.\"\"\"\nimport base64,io,json,re,shutil,subprocess\nfrom pathlib import Path\n\ndef dimensions(source):\n data=json.loads(subprocess.check_output(['ffprobe','-v','error','-protocol_whitelist','file,pipe','-select_streams','v:0','-show_streams','-of','json',str(source)],timeout=30));stream=data['streams'][0];w,h=int(stream['width']),int(stream['height'])\n rotation=next((x['rotation'] for x in stream.get('side_data_list',[]) if 'rotation' in x),stream.get('tags',{}).get('rotate',0))\n if abs(int(rotation))%180==90:w,h=h,w\n if min(w,h)<1 or w*h>33000000:raise ValueError('أبعاد الفيديو كبيرة')\n return w,h\n\ndef number(s,k,a,b,d):\n n=s.get(k,d)\n if isinstance(n,bool) or not isinstance(n,(int,float)) or not a<=n<=b:raise ValueError('قيمة تنسيق غير صالحة')\n return float(n)\n\ndef ass_text(text,s,w,h):\n family={'sans':'DejaVu Sans','amiri':'Amiri'}[s.get('fontFamily','sans')];weight={'400':0,'700':-1}[s.get('fontWeight','400')];color=s.get('fontColor','#ffffff')\n if not re.fullmatch('#[a-fA-F0-9]{6}',color):raise ValueError('لون غير صالح')\n color='&H00'+color[5:7]+color[3:5]+color[1:3];size=h*number(s,'fontSizePct',1,12,4)/100;x=w*number(s,'x',0,100,50)/100;y=h*number(s,'y',0,100,90)/100\n if not isinstance(s.get('background',False),bool):raise ValueError('خلفية غير صالحة')\n header=f'''[Script Info]\nScriptType: v4.00+\nPlayResX: {w}\nPlayResY: {h}\nWrapStyle: 0\nScaledBorderAndShadow: yes\n[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\nStyle: Default,{family},{size:.3f},{color},{color},&H801A211D,&H801A211D,{weight},0,0,0,100,100,0,0,{3 if s.get('background') else 1},{max(1,size*.055):.3f},0,5,{round(w*.05)},{round(w*.05)},0,1\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n'''\n def clock(t):\n  a,b,c,d=map(int,re.split('[:,.]',t))\n  if b>59 or c>59:raise ValueError('توقيت غير صالح')\n  return f'{a}:{b:02}:{c:02}.{d//10:02}'\n out=[]\n for m in re.finditer(r'(\\d{1,3}:\\d{2}:\\d{2}[,.]\\d{3})\\s*-->\\s*(\\d{1,3}:\\d{2}:\\d{2}[,.]\\d{3})[^\\n]*\\n(.*?)(?=\\n\\s*\\n|\\Z)',text.replace('\\r',''),re.S):\n  line=re.sub(r'<[^>]{0,200}>','',m[3]).replace('\\\\','＼').replace('{','｛').replace('}','｝').strip().replace('\\n',r'\\N')\n  if line:out.append(f'Dialogue: 0,{clock(m[1])},{clock(m[2])},Default,,0,0,0,,{{\\\\an5\\\\pos({x:.3f},{y:.3f})}}{line}')\n if not out:raise ValueError('ملف التوقيت لا يحتوي أسطرًا صالحة')\n return header+'\\n'.join(out)+'\\n'\n\ndef fonts(root):\n folder=root/'fonts';folder.mkdir(exist_ok=True)\n try:\n  from madar_fonts import FONT_ASSETS\n  for name,data in FONT_ASSETS.items():\n   if name not in {'DejaVuSans.ttf','DejaVuSans-Bold.ttf','Amiri-Regular.ttf','Amiri-Bold.ttf'}:raise ValueError('خط غير صالح')\n   (folder/name).write_bytes(base64.b64decode(data,validate=True))\n except ModuleNotFoundError:\n  local=Path(__file__).parents[1]/'src'/'fonts'\n  for p in local.glob('*.ttf'):shutil.copyfile(p,folder/p.name)\n return folder\n\ndef burn(source,cfg,root,report,codec,run,legacy_style):\n w,h=dimensions(source);fontdir=fonts(root);s=cfg.get('captionStyle');subtitle=root/('captions.ass' if s else 'captions.srt');subtitle.write_text(ass_text(cfg['subtitles'],s,w,h) if s else cfg['subtitles'],encoding='utf-8');vf=f'subtitles={subtitle}:fontsdir={fontdir}'\n if not s:vf+=f\":force_style='{legacy_style(cfg)}'\"\n inputs=['-i',source];filters=['-vf',vf,'-map','0:v:0','-map','0:a:0?'];logo=cfg.get('logoPng','')\n if logo:\n  from PIL import Image\n  if not isinstance(logo,str) or len(logo)>480000:raise ValueError('الشعار كبير')\n  raw=base64.b64decode(logo,validate=True)\n  if not raw.startswith(b'\\x89PNG\\r\\n\\x1a\\n'):raise ValueError('الشعار ليس PNG')\n  image=Image.open(io.BytesIO(raw))\n  if min(image.size)<1 or image.width*image.height>1048576:raise ValueError('أبعاد الشعار كبيرة')\n  s=s or {};lw=max(1,round(w*number(s,'logoWidth',4,40,15)/100));lh=max(1,round(lw*image.height/image.width))\n  if lh>h:raise ValueError('قلّل حجم الشعار')\n  x=round((w-lw)*number(s,'logoX',0,100,95)/100);y=round((h-lh)*number(s,'logoY',0,100,5)/100);alpha=number(s,'logoOpacity',10,100,100)/100\n  path=root/'logo.png';image.convert('RGBA').resize((lw,lh)).save(path);inputs+=['-loop','1','-i',path];filters=['-filter_complex',f'[0:v]{vf}[text];[1:v]format=rgba,colorchannelmixer=aa={alpha:.4f}[logo];[text][logo]overlay={x}:{y}:shortest=1[v]','-map','[v]','-map','0:a:0?']\n out=root/'result.mp4';tail=['-c:a','aac','-b:a','160k','-map_metadata','-1','-movflags','+faststart',out]\n try:run([*inputs,*filters,*codec,*tail])\n except subprocess.CalledProcessError:\n  if 'h264_nvenc' not in codec:raise\n  report('processing','استكمال تصدير الفيديو على CPU');run([*inputs,*filters,'-c:v','libx264','-preset','veryfast','-crf','23',*tail])\n return out\n";
